export class BodySkin {
    private pos: Vec2;
    private noSmoothPos: Vec2;
    public node: MatchSnakeSpr;
    private skinFlag: number;
    private tag: com.snake.socket.PlayerObject;
    owner: SnakeDetail;

    static INIT_POS: number = -1000000;

    //小地图英雄设置
    smallHeroImg: Laya.Image;
    alpha = 0.3; // 平滑系数（0到1之间），例如每帧调整10%

    /**
     * @param skinFlag 皮肤标识（使用 Constants.snake.skinFlag 中的值）
     * @param pnl 父容器（例如一个 Laya.Sprite 或其他容器）
     * @param skinNo 第几个皮肤 1开始
     * @param tag 节点标签（可用于标识）
     */
    constructor(skinFlag: number, pnl: Laya.Sprite, skinNo: number, tag: com.snake.socket.PlayerObject, _owner: SnakeDetail) {
        this.updateData(skinFlag, pnl, skinNo, tag, _owner);
    }
    getCollisionPoint(): com.snake.socket.PointObject {
        var pointObject = new com.snake.socket.PointObject();
        pointObject.x = this.noSmoothPos.x;
        pointObject.y = this.noSmoothPos.y;

        return pointObject;
    }
    getThead(): com.snake.socket.SnakeObject {
        var head: com.snake.socket.SnakeObject = new com.snake.socket.SnakeObject();
        var pointObject = new com.snake.socket.PointObject();
        var headP = this.owner.getCollisionHeadPosition();
        pointObject.x = headP.x;
        pointObject.y = headP.y;
        head.loc = pointObject;
        return head;
    }
    updateData(skinFlag: number, pnl: Laya.Sprite, skinNo: number, tag: com.snake.socket.PlayerObject, _owner: SnakeDetail) {
        this.pos = new Vec2(BodySkin.INIT_POS, BodySkin.INIT_POS);
        this.noSmoothPos = new Vec2(BodySkin.INIT_POS, BodySkin.INIT_POS);

        this.tag = tag;
        // tag.exp = color;
        this.owner = _owner;
        if (this.owner.isLogicSnake) {
            this.alpha = 1;
        } else {
            this.alpha = 0.3;
        }
        if (skinFlag === Constants.snake.skinFlag.head) {
            let matchSnakeSpr: MatchSnakeSpr = Laya.Pool.getItemByCreateFun(
                MatchSnakeSpr.POOL_NAME,
                GameResourceManager.roleAniPrefab.create,
                GameResourceManager.roleAniPrefab
            );
            matchSnakeSpr.owner = this;
            this.node = matchSnakeSpr;
            matchSnakeSpr.dataSource = { tag: tag, skinNo: skinNo };
            if (!this.owner.isLogicSnake) {
                // 小地图英雄设置
                this.smallHeroImg = new Laya.Image();
                this.updateSmallHeroImg();
                MapManager.img_smallMap.addChild(this.smallHeroImg);
            }
        } else {
            let matchSnakeBodySpr: MatchSnakeSpr = Laya.Pool.getItemByCreateFun(
                MatchSnakeBodySpr.POOL_NAME,
                GameResourceManager.matchSnakeBodyPrefab.create,
                GameResourceManager.matchSnakeBodyPrefab
            );
            matchSnakeBodySpr.owner = this;
            this.node = matchSnakeBodySpr;
            matchSnakeBodySpr.dataSource = { tag: tag, skinNo: skinNo };
        }

        this.skinFlag = skinFlag;

        // (this.node as any).tag = tag;
        if (!this.owner.isLogicSnake) {
            pnl.addChild(this.node);
        }
    }

    public reset(skinFlag: number, pnl: Laya.Sprite, skinNo: number, tag: com.snake.socket.PlayerObject, _owner: SnakeDetail): void {
        this.updateData(skinFlag, pnl, skinNo, tag, _owner);
    }

    public resetForPool(): void {
        this.destroy();
    }

    public destroy(): void {
        SnakeManager.getInstance().removeBodySkin(this);

        if (this.node) {
            Laya.Tween.killAll(this.node);
            this.node.removeSelf();
        }

        if (this.smallHeroImg) {
            this.smallHeroImg.removeSelf();
        }
        this.pos = null;
        this.noSmoothPos = null;
        this.node = null;

        this.owner = null;
        this.tag = null;
    }

    updateSmallHeroImg() {
        if (this.smallHeroImg) {
            if (this.owner.isSelf) {
                this.smallHeroImg.skin = "res/match2/img_dian1.png"; //蓝点
                var w1 = 15;
                var h1 = 15;
                this.smallHeroImg.size(w1, h1);
                this.smallHeroImg.pivot(w1 / 2, h1 / 2);
            } else {
                if (this.owner.tag.roleId == SnakeManager.getInstance().kingId) {
                    this.smallHeroImg.skin = "res/match2/img_phb_icon2.png"; //蛇王点
                    var w2 = 21;
                    var h2 = 19;
                    this.smallHeroImg.size(w2, h2);
                    this.smallHeroImg.pivot(w2 / 2, h2 / 2);
                } else {
                    this.smallHeroImg.skin = "res/match2/img_dian2.png"; //白点
                    var w3 = 4;
                    var h3 = 4;
                    this.smallHeroImg.size(w3, h3);
                    this.smallHeroImg.pivot(w3 / 2, h3 / 2);
                }
            }
        }
    }

    private lastX = 0;
    private lastY = 0;
    public setPosition(v2: Vec2): void {
        if (this.smallHeroImg) {
            var smallP = Tool.fromBigToSmall(v2.x, v2.y);
            var sX = smallP[0];
            var sY = smallP[1];
            this.smallHeroImg.pos(sX, sY);
        }
        var nodeX: number;
        var nodeY: number;

        if (this.pos.x != BodySkin.INIT_POS || this.pos.y != BodySkin.INIT_POS) {
            if (this.isHead) {
                var positionError = Tool.distancePoint(v2.x, v2.y, this.node.x, this.node.y);
                // console.log("==========setPosition positionError:", positionError, ", roleId: " + this.tag.roleId);

                nodeX = Tool.lerp(this.node.x, v2.x, this.alpha);
                nodeY = Tool.lerp(this.node.y, v2.y, this.alpha);
            } else {
                // const alpha = 0.3; // 平滑系数（0到1之间），例如每帧调整10%

                nodeX = Tool.lerp(this.node.x, v2.x, this.alpha);
                nodeY = Tool.lerp(this.node.y, v2.y, this.alpha);
            }
        } else {
            nodeX = v2.x;
            nodeY = v2.y;
        }
        this.node.pos(nodeX, nodeY);
        this.pos.x = nodeX;
        this.pos.y = nodeY;
        this.noSmoothPos.x = v2.x;
        this.noSmoothPos.y = v2.y;
        if (GameSetting.Debug == 2 && this.skinFlag === Constants.snake.skinFlag.head && !this.owner.isLogicSnake) {
            // if (
            //     !this.owner.isLogicSnake &&
            //     this.lastX != 0 &&
            //     this.lastY != 0 &&
            //     ((this.owner.dir == 180 && this.lastX < nodeX) ||
            //         (this.owner.dir == 0 && this.lastX > nodeX) ||
            //         (this.owner.dir == 270 && this.lastY < nodeY) ||
            //         (this.owner.dir == 90 && this.lastY > nodeY))
            // ) {
            //     console.error(
            //         Quick.GetLogTime,
            //         this.tag.roleId +
            //             ", isLogicSnake: " +
            //             this.owner.isLogicSnake +
            //             ", hasConfirmed: " +
            //             "false" +
            //             ": ======= LOC AFTER =====2 " +
            //             FrameSyncManager.getClientRuningFrame(true) +
            //             " clientLoc1: " +
            //             0,
            //         nodeX,
            //         nodeY,
            //         "lastX: " + this.lastX,
            //         "lastY: " + this.lastY
            //     );
            // }
            // this.lastX = nodeX;
            // this.lastY = nodeY;
        }

        // 更新最终可见性
        this.updateFinalVisibility();
    }

    public getPos(): Vec2 {
        return this.pos;
    }

    public getNoSmoothPos(): Vec2 {
        return this.noSmoothPos;
    }
    // gotoDiePos() {
    //     return;
    //     Laya.Tween.to(this.node, { x: this.noSmoothPos.x, y: this.noSmoothPos.y }, 100);
    //     if (this.smallHeroImg) {
    //         var smallP = Tool.fromBigToSmall(this.noSmoothPos.x, this.noSmoothPos.y);
    //         var sX = smallP[0];
    //         var sY = smallP[1];
    //         this.smallHeroImg.pos(sX, sY);
    //     }
    // }
    public setRotation(rotation: number): void {
        this.node.setRotation(rotation);
    }

    public setLocalZOrder(zorder: number): void {
        this.node.zOrder = zorder;
    }

    public updateAlpha(baseScale: number, speedFactor: number): void {
        const dynamicScale = speedFactor == 1 ? 1 : 0.75; // 根据速度动态缩放
        this.node.setAlpha(dynamicScale);
    }

    public updateScale(baseScale: number, speedFactor: number): void {
        const dynamicScale = baseScale * (1 + 0.1 * speedFactor); // 根据速度动态缩放
        // this.setScale(dynamicScale);
    }

    // public setScale(radio: number): void {
    //     this.node.setScale(radio);
    // }

    public getCollisionBodyRadius(): number {
        return this.owner.getCollisionBodyRadius();
        // return this.node.getRadio();
    }

    public setGray(isGray: boolean): void {
        this.node.setGray(isGray);
    }

    public isVisible(): boolean {
        return this.node.visible;
    }

    public getBoundingBox(): Laya.Rectangle {
        let radius: number;
        if (this.isHead) {
            radius = this.owner.suctionRadius;
        } else {
            radius = this.getCollisionBodyRadius();
        }
        if (this.owner.isLogicSnake) {
            return new Laya.Rectangle(this.noSmoothPos.x - radius, this.noSmoothPos.y - radius, radius * 2, radius * 2);
        } else {
            return new Laya.Rectangle(this.pos.x - radius, this.pos.y - radius, radius * 2, radius * 2);
        }
    }

    public getSkinFlag(): number {
        return this.skinFlag;
    }

    public checkCollision(x: number, y: number, radius: number, isLogicSnake: boolean): boolean {
        const center = isLogicSnake ? this.getNoSmoothPos() : this.getPos();
        return MathUtil.distance(center.x, center.y, x, y) < radius + this.getCollisionBodyRadius();
    }

    get isHead() {
        return this.skinFlag === Constants.snake.skinFlag.head;
    }

    setServerPosLog(serverFrame: number, head: com.snake.socket.SnakeObject, _mockSpeedRate: number, mockDirect: number, mockAimDirect: number) {
        if (this.skinFlag === Constants.snake.skinFlag.head) {
            this.node.setServerPosLog(serverFrame, head, _mockSpeedRate, mockDirect, mockAimDirect);
        }
    }

    showLogInHead(tip: string) {
        if (this.skinFlag === Constants.snake.skinFlag.head) {
            this.node.showLogInHead(tip);
        }
    }

    setClientScore(score: number) {
        if (this.skinFlag === Constants.snake.skinFlag.head) {
            this.node.setClientScore(score);
        }
    }

    private _manualVisible: boolean = true; // 新增手动可见性属性
    public setVisible(visible: boolean): void {
        this._manualVisible = visible; // 更新手动可见性状态
        this.updateFinalVisibility(); // 更新最终可见性
        // this.node.visible = visible;
        if (this.smallHeroImg) {
            this.smallHeroImg.visible = visible;
        }
    }

    private updateFinalVisibility(): void {
        const isInScreen = this.checkInScreen();
        const finalVisible = this._manualVisible && isInScreen;
        // 设置节点和小地图图标的可见性
        this.node.visible = finalVisible;
    }
    setFollowIcon(isShow: boolean) {
        this.node.setFollowIcon(isShow);
    }
    private checkInScreen(): boolean {
        // 获取地图根节点偏移量（通过GameMap的root位置）
        const mapRoot = MapManager.gameMap;
        if (!mapRoot) return false;

        // 计算实际偏移量（地图移动方向与坐标相反）
        const offsetX = -mapRoot.x; // 等价于背景偏移量
        const offsetY = -mapRoot.y;

        // 计算节点在屏幕上的实际坐标
        const screenX = this.pos.x - offsetX;
        const screenY = this.pos.y - offsetY;

        // 获取屏幕尺寸（根据设计分辨率）
        const screenWidth = Laya.stage.width;
        const screenHeight = Laya.stage.height;

        // 获取节点实际半径（考虑缩放）
        const radius = this.isHead ? this.owner.suctionRadius : this.getCollisionBodyRadius();

        // 扩展缓冲区域（1.5倍半径）
        const buffer = radius * 1.5;

        // 判断可见性（考虑边缘缓冲）
        return (
            screenX + radius + buffer > 0 && // 右边缘未超出屏幕左侧缓冲
            screenX - radius - buffer < screenWidth && // 左边缘未超出屏幕右侧缓冲
            screenY + radius + buffer > 0 && // 下边缘未超出屏幕顶部缓冲
            screenY - radius - buffer < screenHeight // 上边缘未超出屏幕底部缓冲
        );
    }
}
