    private initGameLanguage(): void {
        GameResourceManager.GameLanguage_URL = "config/language.json";
        Laya.loader.load(GameResourceManager.GameLanguage_URL, Laya.Handler.create(this, this.initGameResource));
    }

    private initGameResource(data: any): void {
        if (data == null) {
            return;
        }
        let obj: Laya.TextResource = GameResourceManager.getInstance().getResBySetURL(GameResourceManager.GameLanguage_URL);
        GameLanguageMgr.initLanTypes(obj.data);
        ComUtil.processLangParameter();
        Laya.loader.clearRes(GameResourceManager.GameLanguage_URL);
        this.onConfigLoaded();
    }

    private onError(err: string): void {}

    private onConfigLoaded(): void {
        // 初始化 链配置信息 TODO::4加载语言包信息
        let spotInfo: SpotInfo = new SpotInfo();
        spotInfo.ID = 4;
        spotInfo.Event = "加载语言包信息";
        PlatFormManager.sendCustumEvent(4, null, spotInfo);

        if (!GameSetting.ignoreLang) {
            GlobalDataManager.m_strLanguage = GameLanguageMgr.getLanIdByType(GameSetting.User_Lan);
        }
        // UI语言包路径，根据当前语言拼接，主要用于界面文本的本地化
        this.m_UILang = "config/lang_english" + GlobalDataManager.m_strLanguage + ".json";
        // 主语言包路径，包含游戏主要文本内容
        this.m_NomalLang = "config/english" + GlobalDataManager.m_strLanguage + ".json";
        // 备用语言包路径，通常用于补充主语言包未覆盖的内容
        this.m_NomalLang1 = "config/english1.json";
        // 错误提示语言包路径，包含错误相关的本地化文本
        this.m_ErrorLang = "config/error" + GlobalDataManager.m_strLanguage + ".json";
        // 将UI语言包加入预加载资源，确保界面文本能及时加载
        this.m_arrPreResource.push(this.m_UILang);
        // 将主语言包加入预加载资源，确保主要文本内容能及时加载
        this.m_arrPreResource.push(this.m_NomalLang);
        // 将备用语言包加入预加载资源，作为主语言包的补充
        this.m_arrPreResource.push(this.m_NomalLang1);
        // 将错误提示语言包加入预加载资源，确保错误提示能及时本地化
        this.m_arrPreResource.push(this.m_ErrorLang);
        // 初始化所有预加载资源的URL信息
        this.initResourceURL(this.m_arrPreResource, true);
        // 初始化初始资源的URL信息
        this.initResourceURL(this.m_arrInitResource, true);
        this.addFont1();
    }

