    private loadDemoResource(): void {
        SheetDataManager.preInit();
        // 3.0的load，同时可以加载2D,3D资源

        // =============== 消消乐 start ===============

        // 加载各种 动物 单元格预制体
        // const cellPrefabs = CELL_ELEMENT_PREFABS;
        const crushPrefab = {
            url: `resources/prefabs/Crush.lh`,
            type: Laya.Loader.HIERARCHY
        };
        const bombWhitePrefab = {
            url: `resources/prefabs/BombWhite.lh`,
            type: Laya.Loader.HIERARCHY
        };
        const cellViewPrefab = {
            url: `resources/prefabs/CellView.lh`,
            type: Laya.Loader.HIERARCHY
        };
        const cardViewPrefab = {
            url: `resources/prefabs/CardView.lh`,
            type: Laya.Loader.HIERARCHY
        };
        const effectPrefabs = [crushPrefab, bombWhitePrefab, cellViewPrefab, cardViewPrefab];

        var CELL_ELEMENT_PREFABS: any[] = [];
        var OBSTACLE_PREFABS: any[] = [];
        var stageCellItems: StageCellItem[] = SheetDataManager.m_dicStageCells.values;
        stageCellItems.forEach((item) => {
            if (item.prefabPath) {
                if (item.type == Constants.CELL_TYPE.OBSTACLE) {
                    OBSTACLE_PREFABS.push({
                        id: item.id,
                        url: item.prefabPath,
                        type: Laya.Loader.HIERARCHY
                    });
                } else {
                    CELL_ELEMENT_PREFABS.push({
                        id: item.id,
                        url: item.prefabPath,
                        type: Laya.Loader.HIERARCHY
                    });
                }
            }
        });

        var allPrefs = [...this.resArr, ...CELL_ELEMENT_PREFABS, ...OBSTACLE_PREFABS, ...effectPrefabs];

        // =============== 消消乐 end ===============

        Laya.loader.load(allPrefs, null, Laya.Handler.create(this, this.onPreAssetPress1, null, false)).then(() => {
            // 加载完成后，处理逻辑
            LoadingManager.init();
            this.damageNumPrefab = Laya.loader.getRes("scenes/match/DamageNumber.lh");
            this.aniSkPrefab = Laya.loader.getRes("scenes/hero/AniSk.lh");
            // // =============== snake start ===============
            // this.roleAniPrefab = Laya.loader.getRes("scenes/match/MatchSnakeSpr.lh");
            // this.matchSnakeBodyPrefab = Laya.loader.getRes("scenes/match/MatchSnakeBodySpr.lh");
            // this.matchSnakeTailPrefab = Laya.loader.getRes("scenes/match/MatchSnakeTailSpr.lh");
            // this.matchSnakeBeanPrefab = Laya.loader.getRes("scenes/match/MatchSnakeBeanSpr.lh");
            // // =============== snake start ===============
            // var roleAniPrefab = this.roleAniPrefab.create();
            // console.log(" ================ roleAniPrefab: " + roleAniPrefab);
            // var snakeBodyPrefab = this.matchSnakeBodyPrefab.create();
            // console.log(" ================ snakeBodyPrefab: " + snakeBodyPrefab);
            //=============== 消消乐 start ===============

            // 缓存元素Prefab
            for (const item of CELL_ELEMENT_PREFABS) {
                const prefab = Laya.loader.getRes(item.url);
                if (prefab) DataManger.elementPrefabs[item.id] = prefab;
            }
            // 缓存障碍物Prefab（遍历OBSTACLE_PREFABS数组）
            for (const item of OBSTACLE_PREFABS) {
                const prefab = Laya.loader.getRes(item.url);
                if (prefab) DataManger.obstaclePrefabs[item.id] = prefab;
            }

            EffectLayer.crushEffect = Laya.loader.getRes(crushPrefab.url);
            EffectLayer.bombWhite = Laya.loader.getRes(bombWhitePrefab.url);
            DataManger.cellViewPrefab = Laya.loader.getRes(cellViewPrefab.url);
            DataManger.cardViewPrefab = Laya.loader.getRes(cardViewPrefab.url);

            // =============== 消消乐 end ===============

            Signal.event(GameEvent.EVENT_BACK_TO_LOGIN);
        });
    }

