    private initResourceURL(data: any, isCommon: boolean = false): void {
        if (data instanceof Array) {
            this.setResURLArr(data, isCommon);
        } else if (data instanceof Object) {
            for (let key in data) {
                this.setResURLArr(data[key], isCommon);
            }
        }
    }

    private setResURLArr(data: any[], isCommon: boolean): void {
        let defaultType: string;
        let url: string;
        for (let i: number = 0; i < data.length; i++) {
            if (isCommon) {
                this.m_commonResource.set(data[i], true);
                url = this.setResURL(data[i]);
                defaultType = this.getTypeFromUrl(url);
                data[i] = { url: url, type: defaultType, size: 1, priority: 1 };
            } else if (this.m_commonResource.get(data[i])) {
                data.splice(i, 1);
                i--;
            } else {
                url = this.setResURL(data[i]);
                defaultType = this.getTypeFromUrl(url);
                data[i] = { url: url, type: defaultType, size: 1, priority: 1 };
            }
        }
    }

    private static _extReg: RegExp = /\.(\w+)\??/g;
    public getTypeFromUrl(url: string): string {
        let { ext, typeId, main, loaderType } = (Laya.Loader as any).getURLInfo(url);
        GameResourceManager._extReg.lastIndex = url.lastIndexOf(".");
        let result: any[] = GameResourceManager._extReg.exec(url);
        if (result && result.length > 1) {
            return result[1].toLowerCase();
        }
        return "text";
    }

    public setResURL(url: string): string {
        return url;
    }

