const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import { ModuleManager } from "../../common/ModuleManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";

import { ModuleName } from "../../global/ModuleName";
import SheetDataManager from "../../global/SheetDataManager";
import { SnakeUpgradeConfirmDialogBase } from "./SnakeUpgradeConfirmDialog.generated";
import GameResourceManager from "../../common/GameResourceManager";
import { SnakeVo } from "../../data/vo/pack/SnakeVo";
import { SnakeItem } from "../../data/sheetItem/snake/SnakeItem";
import { ComUtil } from "../../utils/ComUtil";

@regClass('CfOVPPXnRR6zn7GL7aIjHQ==')
export class SnakeUpgradeConfirmDialog extends SnakeUpgradeConfirmDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    public nftItem: SnakeVo;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_upgrade.on(Laya.Event.CLICK, this, this.toUpGradeDialog);
        // Signal.on("msg_" + com.snake.socket.MessageType.MSG_SNAKE_UPGRADE, this, this.onUpgradeCallback);
    }

    /**
     * 显示购买页信息
     * @param data
     */
    public setOpenData(data: SnakeVo) {
        if (data) {
            this.nftItem = data as SnakeVo;
            console.log("nftItem:", this.nftItem);
            this.initSnake();
        }
    }

    private initSnake(): void {
        let snakeSkinItem = SheetDataManager.m_dicSnakeSkins.get(this.nftItem.skin);
        if(snakeSkinItem){
            this.tf_name.text = GameLanguageMgr.getLanguage(snakeSkinItem.name);
        }
        const hasUpgraded = !this.nftItem.upgrade;
        this.btn_upgrade.disabled = hasUpgraded;

        if (this.nftItem && this.nftItem.skin) {
            // 获取蛇动画的JSON资源
            let snakeAniJson = GameResourceManager.getSnakeAni(`${this.nftItem.skin}`);

            if (this.snake_sk) {
                // 设置动画源
                this.snake_sk.source = snakeAniJson;
                // 显示蛇动画
                this.snake_sk.visible = true;

                // 确保模板已加载后播放动画
                if (this.snake_sk.templet) {
                    this.snake_sk.play("animation", true);
                }
            }
            // 显示星星（稀有度）
            if (this.nftItem.type) {
                this.showStar(this.nftItem.type);
            }   
        }
        var snakeItem: SnakeItem = SheetDataManager.m_dicSnakes.get(this.nftItem.id);
        if (this.nftItem.attr.length <= 0) {
            this.tf_val1.text = `${snakeItem.initLength}`;
            this.tf_val2.text = `${snakeItem.maxLength}`;
            this.tf_val3.text = `${snakeItem.baseSpeed}`;
            this.tf_val4.text = `${snakeItem.accelerationFactor}`;
            this.tf_val5.text = `${snakeItem.suctionRadius}`;
        } else {
            let attr = this.nftItem.attr;
            for (let i = 0; i < attr.length; i++) {
                if (attr[i]) {
                    let attrItem = attr[i].split(",");
                    let index = attrItem[0];
                    let value = attrItem[1];
                    if (index == "1") {
                        var newLen = parseInt(value);
                        var len = snakeItem.initLength;
                        this.tf_val1.text = newLen + "";
                        console.log("ATTR: 计算长度：后端len: " + len + ", newLen: " + newLen);
                    } else if (index == "2") {
                        var maxLength = snakeItem.maxLength;
                        var newMaxLen = parseInt(value);

                        this.tf_val2.text = newMaxLen + "";

                        console.log("ATTR: 计算最大长度：maxLen: " + maxLength + ", maxLength: " + newMaxLen);
                    } else if (index == "3") {
                        var addSpeedRate = parseInt(value);
                        var speed = snakeItem.baseSpeed;

                        var addSpeed = (addSpeedRate / 100) * speed;
                        speed += addSpeed;
                        this.tf_val3.text = ComUtil.formatNumber(speed) + "";
                        // this.speed = Math.floor(this.speed * 10) / 10; // 向下取整后，取一位小数
                        console.log("ATTR: 计算速度：speed: " + speed + ", addSpeed: " + addSpeed);
                    } else if (index == "4") {
                        var addAccelerationFactorRate = parseInt(value);
                        var accelerationFactor = snakeItem.accelerationFactor;

                        var addAccelerationFactor = (addAccelerationFactorRate / 100) * accelerationFactor;
                        accelerationFactor += addAccelerationFactor;
                        this.tf_val4.text = ComUtil.formatNumber(accelerationFactor) + "";
                        // this.speed = Math.floor(this.speed * 10) / 10; // 向下取整后，取一位小数
                        console.log(
                            "ATTR: 计算速度：accelerationFactor: " + accelerationFactor + ", addAccelerationFactor: " + addAccelerationFactor
                        );
                    } else if (index == "5") {
                        var suctionRadius = snakeItem.suctionRadius;
                        var addSuctionRadiusRate = parseInt(value);
                        var addSuctionRadius = (addSuctionRadiusRate / 100) * suctionRadius;
                        suctionRadius += addSuctionRadius;
                        suctionRadius = Math.floor(suctionRadius);
                        this.tf_val5.text = suctionRadius + "";
                        console.log("ATTR: 计算吸食半径：suctionRadius: " + suctionRadius + ", addSuctionRadius: " + addSuctionRadius);
                    }
                }
            }
        }
    }

    private toUpGradeDialog() {
        ModuleManager.intance.openModule(ModuleName.SnakeUpgradeDialog, this.nftItem);
        this.close();
    }

    onDisable(): void {
        this.btn_upgrade.off(Laya.Event.CLICK, this, this.toUpGradeDialog);

        // 销毁动画
        if (this.snake_sk) {
            this.snake_sk.stop();
            this.snake_sk.visible = false;
        }
        // 清除所有定时器
        Laya.timer.clearAll(this);
    }

    private showStar(type: number): void {
        // 星星图片路径
        const starPath = "res/bag/upgrade/img_xing.png";
        // 占位图片路径
        const placeholderPath = "res/bag/upgrade/img_dengji_.png";
        // 获取所有星星图片组件
        const starImages = [this.img_start1, this.img_start2, this.img_start3, this.img_start4];

        // 根据稀有度显示对应数量的星星
        for (let i = 0; i < starImages.length; i++) {
            // 如果索引小于稀有度，显示星星，否则显示占位图
            starImages[i].skin = i < type ? starPath : placeholderPath;
        }
    }
}
