class MatchModel {
    private static _instance: MatchModel;
    public static getInstance(): MatchModel {
        if (!MatchModel._instance) {
            MatchModel._instance = new MatchModel();
        }
        return MatchModel._instance;
    }
    private _inited: boolean = false;

    public constructor() {
        this.init();
    }

    private init(): void {
        if (!this._inited) {
            this._inited = true;
        }
    }

    private _roomDto: RoomDto;
    public get roomDto(): RoomDto {
        return this._roomDto;
    }
    public set roomDto(value: RoomDto) {
        console.log("roomDto: ", value);
        this._roomDto = value;
        // if (value) {
        //     var pid = GlobalDataManager.playerDto.pid;
        //     if (value.watch) {
        //         const isWatcher = value.watch.some((itemId) => itemId === pid);
        //         this.roomWatcher = isWatcher;
        //     }
        // }
    }

    public coolDownTime: number;
    public limitCd: number;
    public startCoolDownTime: number; //开始时准备时间
    public currArenaItem: ArenaItem;
    /** 没有开始前不能打 或者 比赛结束后不能打 */
    public stopAll: boolean = false;
    // /** 是否是房间观看者 */
    // public roomWatcher: boolean = false;
    /** 是否是比赛观看者 */
    public matchWatcher: boolean = false;

    public setRoomAnonymousLabel(txt: string, anonymous = -1): string {
        if (anonymous == -1) {
            anonymous = MatchModel._instance.roomDto.anonymous;
        }
        if (anonymous == 1) {
            // if(!this.roomWatcher && anonymous == 1){
            return StringTool.ANONYMOUS_NAME;
        } else {
            return txt;
        }
    }

    public setMatchAnonymousLabel(txt: string, anonymous = -1): string {
        if (anonymous == -1) {
            anonymous = MatchModel._instance.matchDto.anonymous;
        }
        if (!this.matchWatcher && anonymous == 1) {
            return StringTool.ANONYMOUS_NAME;
        } else {
            return txt;
        }
    }

    public setMatchAnonymousImg(txt: string, anonymous = -1): string {
        if (anonymous == -1) {
            anonymous = MatchModel._instance.matchDto.anonymous;
        }
        if (!this.matchWatcher && anonymous == 1) {
            return null;
        } else {
            return txt;
        }
    }

    private _matchDto: MatchDto;
    public get matchDto(): MatchDto {
        return this._matchDto;
    }
    public set matchDto(value: MatchDto) {
        console.log("matchDto: ", value);
        this._matchDto = value;
        this.matchWatcher = false;
        if (value) {
            var pid = GlobalDataManager.playerDto.pid;
            if (value.watch) {
                const isWatcher = true; // value.watch.some((itemId) => itemId === pid);
                this.matchWatcher = isWatcher;
            }

            // if (value.startTime - value.nowTime > 0) {
            //     this.stopAll = true;
            // } else {
            //     this.stopAll = false;
            // }
        } else {
            // this.stopAll = false;
        }
    }

    public matchCoolDownTime: number;

    // public playerJoinDic: Dictionary;
    // public playerEndDic: Dictionary;
    private heroReadyDic: Dictionary = new Dictionary();
    setMatchRes() {
        this.heroReadyDic = new Dictionary();
        var len = this.roomDto.members.length;
        var loadArr: any[] = [];
        var mapId = this.currArenaItem.mapid;
        if (this.heroReadyDic.get("map_" + mapId) == null) {
            var mapId = MatchModel._instance.currArenaItem.mapid;

            var mapImg = GameResourceManager.getMapImg(mapId);
            loadArr.push(mapImg);
            var mapPrefab = GameResourceManager.getMapPrefab(mapId);
            loadArr.push(mapPrefab);
            this.heroReadyDic.set("map_" + mapId, true);
        }

        for (var i = 0; i < len; i++) {
            var roomPlayer: any = this.roomDto.members[i];
            if (this.heroReadyDic.get(roomPlayer.heroId + "_" + roomPlayer.heroColor) == null) {
                // var heroItem: any = SheetDataManager.intance.m_dicHeros.get(roomPlayer.heroId);
                // var heroRes = GameResourceManager.getHeroHeadRes(heroItem.serialId, roomPlayer.heroColor);
                // var heroSk = GameResourceManager.getHeroSkRes(heroItem.serialId, roomPlayer.heroColor);
                // loadArr.push(heroRes);
                // loadArr.push({ url: heroSk, type: Laya.Loader.SPINE });
                this.heroReadyDic.set(roomPlayer.heroId + "_" + roomPlayer.heroColor, true);
            }
        }

        if (loadArr.length > 0) {
            Laya.loader.load(loadArr, null, Laya.Handler.create(this, this.onPreAssetPress1, null, false)).then(() => {});
        }
    }

    private onPreAssetPress1(value: number): void {}

    msgEndbody: com.snake.socket.SC_GAME_RES;

    onAiSetMatchEnd(msgEndBody: com.snake.socket.SC_GAME_RES) {
        this.msgEndbody = msgEndBody;
        
        RoomWebSocket.isMatching = false; //比赛结束不再使用socket
        MatchModel._instance.stopAll = true;
        Signal.event(GameEvent.EVENT_PLAY_BOSS_RES, msgEndBody);
        this.msgEndbody = msgEndBody;
        Laya.timer.once(4000, this, this.onGoMatchEndView, [EnumMatch.MATCH_TYPE_PVE]);

    }

    onSetMatchEnd(msgEndBody: com.snake.socket.SC_GAME_RES, openNow: boolean = false) {
        let playerDto: PlayerDto = GlobalDataManager.playerDto;
        if (playerDto) {
            playerDto.xxlMMR = msgEndBody.mmr;
        }

        FrameSyncManager.frameNetQueue.isStart = false; //不再处理比赛数据
        this.msgEndbody = msgEndBody;

        if (!msgEndBody.res) {
            RoomWebSocket.closeConnect(); //比赛结束，输了才不再使用socket
        }
        MatchModel._instance.stopAll = true;
        Signal.event(GameEvent.EVENT_PLAY_BOSS_RES, this.msgEndbody); //播放胜利怪物动画

        // console.log("MatchModel.onSetMatchEnd: ", this.msgEndbody);
        Laya.timer.once(4000, this, this.onGoMatchEndView, [EnumMatch.MATCH_TYPE_PVP]);
    }

    onGoMatchEndView(matchType: number) {
        ModuleManager.intance.openModule(ModuleName.MatchEndView, [matchType, this.msgEndbody]);
    }
    onMockMatchEnd() {
        // Laya.timer.clear(this, this.onGoMatchEndRank);
        // if (this.msgEndbody) {
        //     this.onGoMatchEndRank();
        //     // this.msgEndbody = null;
        // } else {
        // }
    }
    clearData() {
        console.log("clearData ");
        Laya.timer.clear(this, this.onGoMatchEndView);
        // this.roomDto = null;
        this.matchDto = null;

        this.msgEndbody = null;

        // this.playerJoinDic = null;
        // this.playerEndDic = null;
        this.heroReadyDic = null;
        this.currArenaItem = null;
        // this.roomWatcher = false;
        this.matchWatcher = false;

        // RoomWebSocket.closeConnect();

        SoundMgr.playMusicByName(SoundMgr.soundName_bg, ".mp3");
        GetItemDataModel.needPop = true;
        GetItemService.startShow();
    }
}
export default MatchModel.getInstance();
