class GameSetting {
    public referral: string = ""; //邀请码
    public showHeartLog: boolean = false;
    public ignoreLang: boolean = false;

    public Debug: number = 0;
    public Res: number = 0;
    /**
     * 是否是测试比赛 测试不走交互，只测试比赛中的逻辑
     */
    public isTest: boolean = false;
    public roomNoTest: string;
    /**
     * 方便后端连本地
     */
    public roomUrlTest: string;

    public gameId: number = 100002; //100001=贪吃蛇 100002=消消乐 100003=俄罗斯方块

    public _LoginType: string = "gamecenter";

    /**
     * 是否是into钱包
     */
    public isInto: boolean = false;

    /**
     * 是否需要画碰撞
     */
    public needDraw: boolean = false;
    /**
     * 是否需要显示FoodId
     */
    public needFoodId: boolean = false;

    /**
     * 是否已经全屏
     */
    public isFull: boolean = false;

    public justFull: boolean = false; //忽略IOS不全屏
    public Login_UDID: string = "81BC19A8-B49B-47CC-BEFE-193E723B521A";
    public Device_Info: string = "";
    public FCM_Token: string = "";
    public APP_IsRelease: boolean = true;
    public User_Lan: string = "en";
    public UserAgent: string = "";
    public Login_UserName: string = "";
    /**
     * 是否白名单 绕过开服通知
     */
    public isWhite: boolean = true;

    /**
     * 是否测试卡牌
     */
    public removeGuides: any[];

    public APP_RES: string = "";

    public COOKIE_CF_LAN: string = "COOKIE_GG_LAN";
    public COOKIE_CF_LoginType: string = "COOKIE_CF_LoginType";
    public IPHONEX_SCARE: number = 1.22;
    public IPHONEX_TOP: number = 44;
    public IPHONEX_BUTTOM: number = 34;
    public DESIGN_WIDTH: number = 750;
    public DESIGN_HEIGHT: number = 1334;
    private static _instance: GameSetting;
    public constructor() {}
    public get LoginType(): string {
        return GameSetting._instance._LoginType;
    }

    public set LoginType(value: string) {
        GameSetting._instance._LoginType = value;
        if (GameSetting._instance._LoginType && GameSetting._instance._LoginType != "") {
            Laya.LocalStorage.setItem(GameSetting._instance.COOKIE_CF_LoginType, GameSetting._instance._LoginType);
        }
    }

    public get isWhiteList(): boolean {
        return true;
    }

    public static getInstance(): GameSetting {
        if (!GameSetting._instance) {
            GameSetting._instance = new GameSetting();
        }
        return GameSetting._instance;
    }

    public get vType(): number {
        return getVType();
    }

    public get requestTime(): number {
        return 0;
    }

    public get loginTime(): number {
        return 0;
    }

    private _m_iTimeFrame: number = 0;
    public set m_iTimeFrame(time: number) {
        if (time > 1500) {
            let cancelTime = function (): void {
                GameSetting._instance._m_iTimeFrame = 0;
            };
            GameSetting._instance._m_iTimeFrame = time;
            Laya.timer.clear(Laya.timer, cancelTime);
            Laya.timer.once(500, Laya.timer, cancelTime);
        }
    }

    public get m_iTimeFrame(): number {
        return GameSetting._instance._m_iTimeFrame;
    }
}
export default GameSetting.getInstance();
