const { regClass } = Laya;
import PlatFormManager from "../../common/PlatFormManager";
import { Quick } from "../../utils/Quick";
import { HelpDialogBase } from "./HelpDialog.generated";

@regClass('xATCTfSDSkaGtuYn669ofQ==')
export class HelpDialog extends HelpDialogBase {
    private canClose: boolean = true;
    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_refresh.on(Laya.Event.CLICK, this, this.onRefresh);
        // 注册超链接点击事件
        this.alertDesc.on(Laya.Event.LINK, this, this.onLink);
    }

    onLink(data: any) {
        console.log("点击了超链接：" + data);
        if (data) {
            Quick.onOpenUrlView(data);
        }
    }
    onRefresh() {
        PlatFormManager.reload();
    }

    public setOpenData(data: any) {
        if (data) {
            var type: number = data[0];
            if (data.length > 2) {
                this.alertTitle.text = data[1] as string;
                this.alertDesc.text = data[2] as string;
            } else {
                this.alertDesc.text = data[1] as string;
            }
            if (type == 1) {
                this.canClose = false;
                var btnClose: Laya.Button = this.getChildByName("close") as Laya.Button;
                btnClose.visible = false;
                this.btn_refresh.visible = true;
            } else {
                this.btn_refresh.visible = false;
            }
            this.alertDesc.height = this.alertDesc.textField.textHeight + 20;
        }
    }

    onDisable(): void {}

    close(type?: string): void {
        if (this.canClose) super.close(type);
    }
}
