import AudioUtils from "../model/AudioUtils";
import { CELL_WIDTH, ANITIME } from "../model/ConstValue";
import DataManger from "../model/DataManger";
import { EffectOpt, EffectCrush, EffectRowBomb, EffectColBomb, EffectWrapBomb, EffectBirdBomb } from "../model/OptCmd";

/**
 * 特效层
 */
class EffectLayer {
    private static _instance: EffectLayer;

    public static getInstance(): EffectLayer {
        if (EffectLayer._instance == null) {
            EffectLayer._instance = new EffectLayer();
            return EffectLayer._instance;
        } else {
            return EffectLayer._instance;
        }
    }

    root: any; // 特效容器
    bombWhite: any; // 爆炸特效预制体
    crushEffect: any; // 消除特效预制体
    //   audioUtils: EffectLayer; // 音频工具

    /**
     * 播放特效
     * @param optList 特效操作列表
     */
    playEffects(optList: EffectOpt[]): void {
        if (!optList || optList.length === 0) return;

        const soundMap: Record<string, boolean> = {};
        console.log("========== optList", optList);

        for (const cmd of optList) {
            // 延迟执行
            Laya.timer.once(cmd.playTime * 1000, this, () => {
                let effect: Laya.Sprite = null;
                let _animator = null;

                // 根据特效类型创建不同效果
                if (cmd instanceof EffectCrush) {
                    effect = this.createCrushEffect(cmd);
                    _animator = effect.getComponent<Laya.Animator2D>(Laya.Animator2D);
                    if (!soundMap[`crush${cmd.playTime}`]) {
                        AudioUtils.playEliminate(cmd.step);
                        soundMap[`crush${cmd.playTime}`] = true;
                    }
                } else if (cmd instanceof EffectRowBomb) {
                    effect = this.createRowBombEffect(cmd);
                    _animator = effect.getComponent<Laya.Animator2D>(Laya.Animator2D);
                } else if (cmd instanceof EffectColBomb) {
                    effect = this.createColBombEffect(cmd);
                    _animator = effect.getComponent<Laya.Animator2D>(Laya.Animator2D);
                } else if (cmd instanceof EffectWrapBomb) {
                    AudioUtils.playCircleEliminate(); //播放消除周围一圈音效
                } else if (cmd instanceof EffectBirdBomb) {
                    AudioUtils.playBirdSwapEliminate(); //播放鸟交换消除同色音效
                    let node = DataManger.findCellNodeByID(cmd.id);
                    if (node) node.playBirdGuangEffect();
                }

                if (effect) {
                    // 设置位置并添加到舞台
                    effect.pos(CELL_WIDTH * (cmd.pos.x - 0.5), CELL_WIDTH * (cmd.pos.y - 0.5));
                    this.root.addChild(effect);

                    // 等待下一帧再播放动画
                    Laya.timer.frameOnce(1, this, () => {
                        if (cmd instanceof EffectCrush) {
                            _animator.play("effect");
                        } else if (cmd instanceof EffectRowBomb) {
                            AudioUtils.playHorizontalEliminate(); //播放横向消除一行音效
                            _animator.play("effect_line");
                        } else if (cmd instanceof EffectColBomb) {
                            _animator.play("effect_col");
                            AudioUtils.playVerticalEliminate(); //播放竖向消除一行音效
                        }
                    });

                    // 使用新的Tween API创建淡出动画
                    Laya.Tween.create(effect)
                        .to("alpha", 0)
                        .duration(ANITIME.DIE * 1000)
                        .then(() => {
                            effect.removeSelf();
                        });
                }
            });
        }
    }

    public test(): void {
        var effect = this.createColBombEffect(null);
        var _animator = effect.getComponent<Laya.Animator2D>(Laya.Animator2D);
        _animator.play("effect_col"); //第一次设置不起作用
        effect.pos(Laya.stage.width / 2, Laya.stage.height / 2);
        Laya.stage.addChild(effect);
        console.log("playEffects: effect_col");

        Laya.timer.frameOnce(1, this, () => {
            _animator.play("effect_col"); //延时设置才起作用
        });
    }

    /**
     * 创建消除特效
     * @param cmd 消除命令
     * @returns 特效精灵
     */
    private createCrushEffect(cmd: EffectCrush): Laya.Sprite {
        const effect = this.crushEffect.create() as Laya.Sprite;
        // 播放动画
        return effect;
    }

    /**
     * 创建行爆炸特效
     * @param cmd 行爆炸命令
     * @returns 特效精灵
     */
    private createRowBombEffect(cmd: EffectRowBomb): Laya.Sprite {
        const effect = this.bombWhite.create() as Laya.Sprite;
        // 设置行爆炸动画
        return effect;
    }

    /**
     * 创建列爆炸特效
     * @param cmd 列爆炸命令
     * @returns 特效精灵
     */
    private createColBombEffect(cmd: EffectColBomb): Laya.Sprite {
        const effect = this.bombWhite.create() as Laya.Sprite;
        // 设置列爆炸动画
        return effect;
    }
}

export default EffectLayer.getInstance();
