    showOpt(opt: Opt): void {
        this.playOptAudio(opt);
        this.showCellOpt(opt.cellOptList);
        this.showEffectOpt(opt.effectOptList);
    }

    private playOptAudio(opt: Opt): void {
        if (opt.optType === OptType.Swap || opt.optType === OptType.Crush) {
            AudioUtils.playSwap();
        } else {
            AudioUtils.playClick();
        }
    }

    /**
     * 显示单元格操作
     * @param optList 单元格操作列表
     */
    private showCellOpt(optList: CellOpt[]): void {
        if (!optList || optList.length === 0) return;

        for (const cellOpt of optList) {
            let node = DataManger.findCellNodeByID(cellOpt.id);
            const actions: any[] = [];
            let curTime = 0;

            for (const cmd of cellOpt.cmdList) {
                // 添加延迟
                if (cmd.playTime > curTime) {
                    actions.push({
                        delay: (cmd.playTime - curTime) * 1000
                    });
                }

                // 处理不同命令
                if (cmd instanceof CellCreate) {
                    node = this.getCreateCell(cellOpt, cmd);
                    actions.push({
                        callback: () => {
                            node.alpha = 1; // 设置可见
                        }
                    });
                } else if (cmd instanceof CellSelect) {
                    if (!node) {
                        console.log("cellView", node, cellOpt.id);
                    }
                    // actions.push({
                    //   callback: () => {
                    const cellView = node as CellView;
                    //   const cellView = node.getComponent(CellView) as CellView;
                    cellView.setSelect(cmd.status);
                    //   },
                    // });
                } else if (cmd instanceof CellMoveTo) {
                    const targetX = CELL_WIDTH * (cmd.pos.x - 0.5);
                    const targetY = CELL_HEIGHT * (cmd.pos.y - 0.5);
                    const startX = node.x;
                    const startY = node.y;

                    // 获取动物类型信息
                    let animalName = "未知";
                    if (cellOpt.type) {
                        const cellCfg = SheetDataManager.m_dicStageCells.get(cellOpt.type);
                        if (cellCfg && cellCfg.name) {
                            animalName = cellCfg.name;
                        }
                    }
                    console.log(
                        Quick.GetLogTime +
                            `[ANIM_DEBUG] 🎯 CellMoveTo命令: 动物=${animalName}(${cellOpt.type}) 起始位置=(${cellOpt.startX}, ${cellOpt.startY}) 目标位置=(${cmd.pos.x}, ${cmd.pos.y}) playTime=${cmd.playTime} keepTime=${cmd.keepTime}`
                    );
                    // console.log(Quick.GetLogTime + " moveTo: ",
                    //   "animal:", animalName, "(type:" + cellOpt.type + ")",
                    //   "from(", startX, ",", startY, ") to(", targetX, ",", targetY, ")",
                    //   "cmd.pos.x:", cmd.pos.x, "cmd.pos.y:", cmd.pos.y,
                    //   "cmd.keepTime:", cmd.keepTime, cmd);

                    actions.push({
                        moveTo: { x: targetX, y: targetY },
                        duration: cmd.keepTime * 1000
                    });
                } else if (cmd instanceof CellDie) {
                    actions.push({
                        callback: () => {
                            node.readyDie();
                        }
                    });
                } else if (cmd instanceof CellShare) {
                    actions.push({
                        shake: true,
                        duration: cmd.keepTime * 1000
                    });
                }

                curTime = cmd.playTime + cmd.keepTime;
            }

            // 执行动作序列
            node.runActions(actions);
        }
    }

