import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import { com } from "../../network/pb/socket";
import { AnimationUtil } from "../../utils/AnimationUtil";
import { SnakeUpgradeSuccessDialogBase } from "./SnakeUpgradeSuccessDialog.generated";

const { regClass } = Laya;

@regClass('OjPqAteAQeOIAjHFO+yihA==')
export class SnakeUpgradeSuccessDialog extends SnakeUpgradeSuccessDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    public constructor() {
        super();
    }

    onEnable(): void {
        this.alertTitle.text = GameLanguageMgr.getLanguage(74);
        this.backLayer.alpha = 0;
        this.backLayer.visible = true;
        Laya.Tween.to(this.backLayer, { alpha: 1 }, 200, Laya.Ease.linearIn);
        // 给this.img_this加一个一直旋转的动画，onDisable的时候销毁掉
        this.initProp();
    }

    /**
     * 显示购买页信息
     * @param data
     */
    public setOpenData(data: com.snake.socket.SC_SNAKE_UPGRADE) {
        if (data) {
            let attr = data.snake.attr;
            for (let i = 0; i < attr.length; i++) {
                if (attr[i]) {
                    let attrItem = attr[i].split(",");
                    let index = attrItem[0];
                    let value = attrItem[1];
                    (this as any)["upgradeAwarditem_" + index].getChildByName("tf_award").text = value;
                }
            }
        }
    }

    onDisable(): void {
        // Laya.Tween.killAll(this.img_guang);
    }

    private initProp() {
        AnimationUtil.startElasticPopupAnimation(this.img_di, 150, 1.1, 100, 0.95, 80);
        this.box_snake.source = "gameIcon/spine/snakeUpgrade/img_shengj.json";
        this.box_snake.on(Laya.Event.COMPLETE, this, this.onAnimationComplete);
        Laya.timer.once(1300, this, this.onAnimationComplete);
    }

    private onAnimationComplete(): void {
        this.box_snake.off(Laya.Event.COMPLETE, this, this.onAnimationComplete);
        if (this.box_snake.animationName === "animation1") {
            this.box_snake.play("animation2", true);
        }
    }
}
