const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import { ModuleManager } from "../../common/ModuleManager";
import SceneManager from "../../common/SceneManager";
import { PlayerDto } from "../../data/dto/PlayerDto";
import { EnumMatch } from "../../data/enumData/EnumMatch";
import { LevelItem } from "../../data/sheetItem/role/LevelItem";
import GameControl from "../../game/match/GameControl";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import { SocketEvent } from "../../global/event/SocketEvent";
import GlobalDataManager from "../../global/GlobalDataManager";
import { ModuleName } from "../../global/ModuleName";
import SheetDataManager from "../../global/SheetDataManager";
import { com } from "../../network/pb/socket";
import RoomWebSocket from "../../network/RoomWebSocket";
import { ComUtil } from "../../utils/ComUtil";
import { Quick } from "../../utils/Quick";
import { TimeUtil } from "../../utils/TimeUtil";
import NoticeMgr from "../notice/NoticeMgr";
import { ArenaVSSceneBase } from "./ArenaVSScene.generated";
import MatchModel from "./MatchModel";

@regClass('CHTz/rcIR1e3hkXcr9Qyvw==')
export class ArenaVSScene extends ArenaVSSceneBase {
    public m_iLayerType: number;
    public m_iPositionType: number;

    private matchCoolDownTime: number = 0;
    private tipLenId: number = 0;

    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }

    onOpened(_type: any): void {
        Signal.on(GameEvent.EVENT_PVP_INIT_DATA, this, this.onInitData);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CUSTOM_MATCH, this, this.onCustomMatch);

        this.tf_reduceTime.text = TimeUtil.format(this.matchCoolDownTime, ":", false);
        // this.btn_startGame.on(Laya.Event.CLICK, this, this.onStartVs);
        this.btn_close.on(Laya.Event.CLICK, this, this.onExitVs);
        this.btn_invite.on(Laya.Event.CLICK, this, this.onInviteClick);

        if (EnumMatch.arenaType == EnumMatch.ARENA_TYPE_CUSTOM) {
            var target = MatchModel.roomDto.target; //邀请自己的人
            if (target) {
                this.btn_invite.visible = false;
            } else {
                this.btn_invite.visible = true;
            }
            this.tipLenId = 2012; //等待中: {0}
        } else {
            this.btn_invite.visible = false;
            this.tipLenId = 3003; //匹配中: {0}
        }

        this.setMyInfo();
        this.setOtherInfo(null);
        this.onStartVs(_type);

        // MatchModel.matchDto.otherPlayerObject = MatchModel.matchDto.myPlayerObject = Glob;

        // this.onInitData();
    }

    onStartVs(_type: number) {
        this.btn_startGame.disabled = true;

        this.updateBattleCD();
        if (_type == 1) {
            //第一次未连接socket
            GameControl.onConnectRoom(); //第一次连接房间
        } else if (_type == 2) {
            Signal.event(SocketEvent.EVENT_ROOM_START_VS_ROOM);
        }
    }
    onExitVs() {
        var cmdId = com.snake.socket.MessageType.MSG_OUT_MATCH;

        RoomWebSocket.sendData(cmdId, null);

        MatchModel.roomDto = null;
        RoomWebSocket.closeConnect();

        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    }

    public setMyInfo(): void {
        let playerDto: PlayerDto = GlobalDataManager.playerDto;
        if (!playerDto) return;
        this.tf_roleName_1.text = ComUtil.fitTextToLabel(playerDto.name, this.tf_roleName_1);
        // playerDto.needTip = true;
        this.playerIcon_1.dataSource = playerDto;
        // this.tf_lv_1.text = `${playerDto.lv}`;
        this.tf_score_1.text = GameLanguageMgr.getUILang("Score") + `: ${playerDto.xxlMMR}`;
        let levelItem: LevelItem = SheetDataManager.getLevelById(playerDto.lv);
        // this.prog_exp_1.value = playerDto.exp / levelItem.needExp;
    }

    public updateBattleCD(): void {
        this.matchCoolDownTime = 0;

        this.onSetCoolTime();
        Laya.timer.loop(1000, this, this.onSetCoolTime);
    }

    private onSetCoolTime(): void {
        var time = TimeUtil.format(this.matchCoolDownTime, ":", false);
        this.tf_reduceTime.text = GameLanguageMgr.getLanguage(this.tipLenId, time); //匹配中: {0}

        this.matchCoolDownTime++;
    }

    private onInitData() {
        var otherPlayerObject = MatchModel.matchDto.otherPlayerObject;

        if (otherPlayerObject) {
            this.btn_close.visible = false;
            this.btn_invite.visible = false;
            Laya.timer.clear(this, this.onSetCoolTime);
            this.tf_reduceTime.text = GameLanguageMgr.getLanguage(3002); // "匹配成功";
            this.setOtherInfo(otherPlayerObject);
            Laya.timer.once(2000, this, this.goMatchScene);
        }
    }

    private goMatchScene() {
        ModuleManager.intance.closeAll();
        SceneManager.isCloseAll = false;
        ModuleManager.intance.openModule(ModuleName.MatchReadyView); //增加过渡页

        SceneManager.setCurrentScene(SceneType.M_SCENE_SNAKE_MATCH);
    }

    private setOtherInfo(playerDto: com.snake.socket.PlayerObject): void {
        if (playerDto) {
            this.tf_roleName_2.text = ComUtil.fitTextToLabel(playerDto.userName, this.tf_roleName_2);
            // playerDto.needTip = true;
            this.playerIcon_2.headSkin = playerDto.icon;
            this.playerIcon_2.visible = true;
            this.img_wenhao.visible = false;
            // this.tf_lv_2.text = `${playerDto.lv}`;
            this.tf_score_2.text = GameLanguageMgr.getUILang("Score") + `: ${playerDto.xxlMMR}`;
            let levelItem: LevelItem = SheetDataManager.getLevelById(playerDto.lv);
            // this.prog_exp_2.value = playerDto.exp / levelItem.needExp;
        } else {
            this.tf_roleName_2.text = "";
            // playerDto.needTip = true;
            this.playerIcon_2.visible = false;
            this.img_wenhao.visible = true;
            this.tf_score_2.text = "";
            // this.tf_lv_2.text = `0`;

            // this.prog_exp_2.value = 0;
        }
    }

    private onInviteClick(): void {
        var pvpRoomIndex = MatchModel.roomDto.tabIndex;
        if (pvpRoomIndex < 0) {
            pvpRoomIndex = 0;
        }
        var pvpTokenIndex = MatchModel.roomDto.tokenIndex;
        if (pvpTokenIndex < 0) {
            pvpTokenIndex = 0;
        }

        // 创建包含房间信息的对象
        const roomInfo = {
            arenaType: EnumMatch.ARENA_TYPE_CUSTOM,
            tabIndex: pvpRoomIndex,
            tokenIndex: pvpTokenIndex,
            target: GlobalDataManager.playerDto.pid
        };

        // 添加room参数
        var code = JSON.stringify(roomInfo);

        const inviteUrl = Quick.getCustomRoomInviteUrl(code);
        doCopy(inviteUrl);
        NoticeMgr.notice(GameLanguageMgr.getLanguage(2011)); //复制成功，转发给好友。
    }
    /**
     * 处理资产变更记录响应
     */
    private onCustomMatch(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        if (msgcode == com.snake.socket.MessageCode.MATCH_IN_FIGHT) {
            Quick.popWithCallBack(2008, true, this.onExitVs);
        }
    }

    onDisable(): void {
        Signal.off(GameEvent.EVENT_PVP_INIT_DATA, this, this.onInitData);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CUSTOM_MATCH, this, this.onCustomMatch);
        Laya.timer.clearAll(this);
    }
}
