export class CookieUtil {
    public constructor() {
        let document: any = Laya.Browser.window.document;
    }
    public static setCookie(name: string, value: string, expireMs = 86400000): void {
        const expires = new Date(Date.now() + expireMs).toUTCString();
        document.cookie = `${name}=${encodeURIComponent(value)}; expires=${expires}; path=/`;
    }
    public static getCookie(name: string): string {
        return document.cookie
            .split('; ')
            .find(row => row.startsWith(name + '='))
            ?.split('=')[1] || null;
    }
    public static deleteCookie(name: string): void {
        document.cookie = `${name}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/`;
    }
}
