import GameResourceManager from "./GameResourceManager";

class SoundMgr {
    public static COOKIE_CF_MUSIC: string = "COOKIE_CF_MUSIC";
    public static COOKIE_CF_SOUND: string = "COOKIE_CF_SOUND";
    private static _instance: SoundMgr;
    public static getInstance(): SoundMgr {
        if (!SoundMgr._instance) {
            SoundMgr._instance = new SoundMgr();
        }
        return SoundMgr._instance;
    }
    private constructor() {
        // console.log("SoundMgr init");
        // Laya.SoundManager.autoStopMusic = true;
    }

    /**背景音乐 */
    private _m_bPlayMusic: boolean = true;

    /**音效 */
    private _m_bPlayeSound: boolean = true;
    public m_strMusicURL: string;

    /**背景音乐 */
    public get m_bPlayMusic(): boolean {
        return this._m_bPlayMusic;
    }

    /**背景音乐 */
    public set m_bPlayMusic(value: boolean) {
        this._m_bPlayMusic = value;
        if (value) {
            if (this.m_strMusicURL != null) this.playMusicByURL(this.m_strMusicURL);
        } else {
            if (this.musicChannel) {
                this.musicChannel.stop();
            }
        }
    }

    private _musicVolume: number = 1;
    private _soundVolume: number = 1;

    /**获取背景音乐音量 */
    public getMusicVolume(): number {
        return this._musicVolume;
    }

    /**设置背景音乐音量 */
    public setMusicVolume(volume: number): void {
        this._musicVolume = volume;
        Laya.SoundManager.setMusicVolume(volume);
        this.saveMusicVolume();
    }

    /**获取音效音量 */
    public getSoundVolume(): number {
        return this._soundVolume;
    }

    /**设置音效音量 */
    public setSoundVolume(volume: number): void {
        this._soundVolume = volume;
        Laya.SoundManager.setSoundVolume(volume);
        this.saveSoundVolume();
    }

    /**保存背景音乐音量到localStorage */
    private saveMusicVolume(): void {
        Laya.LocalStorage.setItem(SoundMgr.COOKIE_CF_MUSIC, this._musicVolume.toString());
    }

    /**保存音效音量到localStorage */
    private saveSoundVolume(): void {
        Laya.LocalStorage.setItem(SoundMgr.COOKIE_CF_SOUND, this._soundVolume.toString());
    }

    /**从localStorage加载音量设置 */
    private loadVolumeSettings(): void {
        const musicVolume = Laya.LocalStorage.getItem(SoundMgr.COOKIE_CF_MUSIC);
        if (musicVolume != null && musicVolume !== "") {
            this._musicVolume = parseFloat(musicVolume);
            Laya.SoundManager.setMusicVolume(this._musicVolume);
        }

        const soundVolume = Laya.LocalStorage.getItem(SoundMgr.COOKIE_CF_SOUND);
        if (soundVolume != null && soundVolume !== "") {
            this._soundVolume = parseFloat(soundVolume);
            Laya.SoundManager.setSoundVolume(this._soundVolume);
        }
    }

    public init(): void {
        // 从localStorage加载音量设置
        this.loadVolumeSettings();
        // 设置音乐和音效的开关状态
        let cookieMusic: string = Laya.LocalStorage.getItem(SoundMgr.COOKIE_CF_MUSIC);
        if (cookieMusic != null && cookieMusic != "") {
            this.m_bPlayMusic = parseFloat(cookieMusic) > 0;
        }
        let cookieSound: string = Laya.LocalStorage.getItem(SoundMgr.COOKIE_CF_SOUND);
        if (cookieSound != null && cookieSound != "") {
            this.m_bPlayeSound = parseFloat(cookieSound) > 0;
        }
        // 根据开关状态设置实际音量
        this.switchMusic(this.m_bPlayMusic);
        this.switchSound(this.m_bPlayeSound);
        Laya.stage.on(Laya.Event.VISIBILITY_CHANGE, this, this.onVisibilityChange);
        Laya.stage.on(Laya.Event.FOCUS, this, this.onOpenMusicAndSound);
        Laya.stage.on(Laya.Event.BLUR, this, this.onCloseMusicAndSound);
    }
    onVisibilityChange() {
        console.log("onVisibilityChange");
        if (Laya.stage.isVisibility) {
            this.onOpenMusicAndSound(); //播放背景音乐
        } else {
            this.onCloseMusicAndSound(); //关闭背景音乐
        }
    }
    onOpenMusicAndSound() {
        this.switchMusic(true); //播放背景音乐
        this.switchSound(true);

        // 重新播放当前音乐
        if (this.m_bPlayMusic && this.m_strMusicURL) {
            this.playMusicByURL(this.m_strMusicURL);
        }
    }
    onCloseMusicAndSound() {
        this.switchMusic(false); //关闭背景音乐
        this.switchSound(false);
    }
    /**音效 */
    public get m_bPlayeSound(): boolean {
        return this._m_bPlayeSound;
    }

    /**音效 */
    public set m_bPlayeSound(value: boolean) {
        this._m_bPlayeSound = value;
    }
    private musicChannel: Laya.SoundChannel;

    /**背景音乐 */
    public playMusicByURL(url: string): void {
        if (!this.m_bPlayMusic) {
            return;
        }
        if (this.m_strMusicURL) {
        }
        if (this.m_strMusicURL == url && this.musicChannel) {
        }
        this.m_strMusicURL = url;
        Laya.SoundManager.stopMusic();
        this.musicChannel = Laya.SoundManager.playMusic(url, 0, new Laya.Handler(this, this.onComplete));
    }

    /**背景音乐 */
    public playMusicByName(name: string, pix: string = ".ogg"): void {
        let url: string = GameResourceManager.getSoundURL(name, pix);
        this.playMusicByURL(url);
    }

    /**音效 */
    public playSound(url: string, loops: number = 1): void {
        if (!this.m_bPlayeSound) {
            return;
        }
        Laya.SoundManager.playSound(url, loops, new Laya.Handler(this, this.onComplete));
    }

    /**音效 */
    public playSoundByName(name: string, loops: number = 1): void {
        let url: string = GameResourceManager.getSoundURLogg(name);
        this.playSound(url, loops);
    }

    /**音效 */
    public stopSoundByName(name: string): void {
        let url: string = GameResourceManager.getSoundURLogg(name);
        Laya.SoundManager.stopSound(url);
    }

    /**背景音乐 */
    public switchMusic(isOpen: boolean): void {
        const volume = isOpen ? this._musicVolume : 0;
        Laya.SoundManager.setMusicVolume(volume);
        SoundMgr.getInstance().m_bPlayMusic = isOpen;
    }

    /**音效 */
    public switchSound(isOpen: boolean): void {
        const volume = isOpen ? this._soundVolume : 0;
        Laya.SoundManager.setSoundVolume(volume);
        SoundMgr.getInstance().m_bPlayeSound = isOpen;
    }

    public soundName_bg: string = "bgm";
    public soundName_hit: string = "hit.mp3";
    public soundName_snakeBuy: string = "snakeBuy.mp3";
    public soundName_snakeUpdate: string = "snakeUpdate.mp3";
    public soundName_win: string = "result_win.mp3";
    public soundName_fail: string = "result_fail.mp3";
    public soundName_kill_1: string = "kill_1.mp3";
    public soundName_kill_2: string = "kill_2.mp3";
    public soundName_kill_3: string = "kill_3.mp3";
    public soundName_kill_4: string = "kill_4.mp3";
    public soundName_kill_5: string = "kill_5.mp3";
    public soundName_kill_t_3: string = "kill_t_3.mp3";
    public soundName_kill_t_5: string = "kill_t_5.mp3";
    public soundName_kill_t_8: string = "kill_t_8.mp3";
    public soundName_flyHit: string = "flyHit.mp3";

    public soundName_kill_die: string = "kill_die.mp3";
    public soundName_magic: string = "magic.mp3";
    public soundName_hitMe: string = "hitMe.mp3";
    public soundName_iceblock_break: string = "iceblock_break.mp3";

    public soundName_swap_lineline: string = "swap_lineline.mp3";
    public soundName_swap_wrapline: string = "swap_wrapline.mp3";
    public soundName_swap_wrapwrap: string = "swap_wrapwrap.mp3";
    public soundName_swap_colorcolor: string = "swap_colorcolor.mp3";

    public soundName32: string = "ui32.ogg";

    private onComplete(): void {}
}
export default SoundMgr.getInstance();
