const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { ClubItem } from "../../data/sheetItem/club/ClubItem";
import Signal from "../../global/event/Signal";
import GlobalDataManager from "../../global/GlobalDataManager";
import SheetDataManager from "../../global/SheetDataManager";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import NoticeMgr from "../notice/NoticeMgr";
import { CreateClubDialogBase } from "./CreateClubDialog.generated";

@regClass('7vh7JPfDTn2jn2qa3Tzn4A==')
export class CreateClubDialog extends CreateClubDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private clubType: number = 1;
    private isCreating: boolean = false;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.btn_create.on(Laya.Event.CLICK, this, this.onCreate);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_CREATE_CLUB, this, this.onCreateSuccess);
        this.list_clubType.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_clubType.selectHandler = new Laya.Handler(this, this.handleSelectToken);
        this.ClubBox.on(Laya.Event.CLICK, this, this.showSelecePanel);
        this.btn_hideBox.on(Laya.Event.CLICK, this, this.onCloseTab);
        this.initCreateClubData()
    }

    /**
     * 初始化创建俱乐部内容
     */
    private initCreateClubData() {
        let clubData = SheetDataManager.m_dicClub.values;
        this.list_clubType.array = clubData;
        this.list_clubType.selectedIndex = 0;
    }

    private onCreate() {
        if (this.isCreating) {
            return;
        }

        this.isCreating = true;

        const cmdId = com.snake.socket.MessageType.MSG_CREATE_CLUB;
        const requestData = com.snake.socket.CS_CREATE_CLUB.fromObject({
            name: "CLUB",
            icon: "1",
            type: this.clubType
        });
        HallWebSocket.send(cmdId, requestData);
        // SceneManager.setCurrentScene(SceneType.M_SCENE_CLUB);

        Laya.timer.once(3000, this, () => {
            this.isCreating = false;
        });
    }

    public onCreateSuccess(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_CREATE_CLUB = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_CREATE_CLUB);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(79));
            console.log("SC_WITHDRAW MsgBody", msgBody);
            GlobalDataManager.playerDto.club = `${msgBody.clubId}`;
            SceneManager.setCurrentScene(SceneType.M_SCENE_CLUB, msgBody);
            this.close();
        } else if (msgcode == com.snake.socket.MessageCode.NOT_ENOUGH_TOKEN) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(72));
        } else {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(80));
        }
    }

    /**
     * 列表项渲染处理
     */
    private onTokenItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_clubType.selectedIndex == index);
        }
    }

    /**
     * 代币选择处理
     */
    private handleSelectToken(index: number): void {
        if (index != -1) {
            const item: ClubItem = this.list_clubType.selectedItem;
            this.tf_clubType.text = GameLanguageMgr.getLanguage(item.name);
            this.tf_maxMember.text = `${item.maxMember}`;
            this.tf_MaxRoom.text = `${item.maxRoom}`;
            this.tf_referrCommission.text = `${item.ownerCommission}`;
            this.tf_referralCommission.text = `${item.referalCommission}`;
            this.tf_points.text = `${item.fightReward}`;
            this.tf_dayCard.text = `${item.dailyRoom}`;
            this.tf_weekCard.text = `${item.weeklyRoom}`;
            this.tf_price.text = `${item.price} USDT`
            this.clubType = item.id;
        }
        this.img_club_pad.visible = false;
        this.btn_hideBox.visible = false;
    }

    private showSelecePanel() {
        this.img_club_pad.visible = true;
        this.btn_hideBox.visible = true;
    }

    private onCloseTab(): void {
        if (this.img_club_pad.visible) {
            this.btn_hideBox.visible = false;
            this.img_club_pad.visible = false;
        }
    }

    onDisable(): void {
        this.btn_create.off(Laya.Event.CLICK, this, this.onCreate);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_CREATE_CLUB, this, this.onCreateSuccess);
        this.ClubBox.off(Laya.Event.CLICK, this, this.showSelecePanel);
        this.btn_hideBox.off(Laya.Event.CLICK, this, this.onCloseTab);

        Laya.timer.clear(this, () => {
            this.isCreating = false;
        });
    }
}
