import GameLanguageMgr from "../../common/GameLanguageMgr";
import { PraiseSoundManager } from "./PraiseSoundManager";

/**
 * 称赞级别枚举
 */
export enum PraiseLevel {
    GOOD = "good", // 好 (3-4个消除)
    GREAT = "great", // 很好 (5-6个消除)
    AMAZING = "amazing", // 太棒了 (7-8个消除)
    PERFECT = "perfect", // 完美 (9-10个消除)
    INCREDIBLE = "incredible", // 不可思议 (11-12个消除)
    LEGENDARY = "legendary" // 传说 (13+个消除)
}

/**
 * 称赞配置
 */
interface PraiseConfig {
    level: PraiseLevel;
    text: string;
    color: string;
    fontSize: number;
    sound: string;
    particleCount: number;
    scale: number;
    duration: number;
}

/**
 * 连续消除称赞系统
 */
export class ComboPraiseSystem {
    private static _instance: ComboPraiseSystem;
    private container: Laya.Sprite;
    private comboCount: number = 0;
    private lastEliminateTime: number = 0;
    private comboTimeout: number = 3000; // 连击超时时间(ms)
    private isShowingPraise: boolean = false;
    private soundManager: PraiseSoundManager;

    // 称赞配置
    private praiseConfigs: PraiseConfig[] = [
        {
            level: PraiseLevel.GOOD,
            // text: "好!",
            text: "100002_4",
            color: "#4ECDC4",
            fontSize: 24,
            sound: "good",
            particleCount: 10,
            scale: 1.0,
            duration: 1000
        },
        {
            level: PraiseLevel.GREAT,
            // text: "很好!",
            text: "100002_5",
            color: "#45B7D1",
            fontSize: 28,
            sound: "great",
            particleCount: 15,
            scale: 1.2,
            duration: 1200
        },
        {
            level: PraiseLevel.AMAZING,
            // text: "太棒了!",
            text: "100002_6",
            color: "#96CEB4",
            fontSize: 32,
            sound: "amazing",
            particleCount: 20,
            scale: 1.4,
            duration: 1400
        },
        {
            level: PraiseLevel.PERFECT,
            // text: "完美!",
            text: "100002_7",
            color: "#FFEAA7",
            fontSize: 36,
            sound: "perfect",
            particleCount: 25,
            scale: 1.6,
            duration: 1600
        },
        {
            level: PraiseLevel.INCREDIBLE,
            // text: "不可思议!",
            text: "100002_8",
            color: "#DDA0DD",
            fontSize: 40,
            sound: "incredible",
            particleCount: 30,
            scale: 1.8,
            duration: 1800
        },
        {
            level: PraiseLevel.LEGENDARY,
            // text: "传说!",
            text: "100002_9",
            color: "#FF6B6B",
            fontSize: 44,
            sound: "legendary",
            particleCount: 40,
            scale: 2.0,
            duration: 2000
        }
    ];

    public static getInstance(): ComboPraiseSystem {
        if (!ComboPraiseSystem._instance) {
            ComboPraiseSystem._instance = new ComboPraiseSystem();
        }
        return ComboPraiseSystem._instance;
    }

    constructor() {
        this.container = new Laya.Sprite();
        this.soundManager = PraiseSoundManager.getInstance();
    }

    /**
     * 初始化称赞系统
     * @param parent 父容器
     */
    public init(parent: Laya.Sprite): void {
        parent.addChild(this.container);
        this.resetCombo();
    }

    /**
     * 处理消除事件
     * @param eliminateCount 消除数量
     * @param isSpecial 是否特殊消除
     */
    public onEliminate(eliminateCount: number, isSpecial: boolean): void {
        const currentTime = Date.now();

        // 检查是否在连击时间内
        if (currentTime - this.lastEliminateTime < this.comboTimeout) {
            this.comboCount++;
            // 播放连续匹配音效
            // AudioUtils.playContinuousMatch(eliminateCount);
        } else {
            this.comboCount = 1;
        }

        this.lastEliminateTime = currentTime;

        // 根据消除数量确定称赞级别
        const praiseLevel = this.getPraiseLevel(eliminateCount, this.comboCount, isSpecial);


        if (praiseLevel) {
            this.showPraise(praiseLevel, eliminateCount);
        }

        // 设置连击超时
        this.setComboTimeout();
    }

    /**
     * 获取称赞级别
     * @param eliminateCount 消除数量
     * @param comboCount 连击数
     * @param isSpecial 是否特殊消除
     */
    private getPraiseLevel(eliminateCount: number, comboCount: number, isSpecial: boolean): PraiseLevel | null {
        // 特殊消除直接给予高级别称赞
        if (isSpecial) {
            return PraiseLevel.PERFECT;
        }

        // 根据消除数量确定基础级别
        let baseLevel: PraiseLevel;
        if (eliminateCount >= 13) {
            baseLevel = PraiseLevel.LEGENDARY;
        } else if (eliminateCount >= 11) {
            baseLevel = PraiseLevel.INCREDIBLE;
        } else if (eliminateCount >= 9) {
            baseLevel = PraiseLevel.PERFECT;
        } else if (eliminateCount >= 7) {
            baseLevel = PraiseLevel.AMAZING;
        } else if (eliminateCount >= 5) {
            baseLevel = PraiseLevel.GREAT;
        } else if (eliminateCount >= 3) {
            baseLevel = PraiseLevel.GOOD;
        } else {
            return null; // 不显示称赞
        }

        // 连击加成
        if (comboCount >= 5) {
            // 连击5次以上，提升一个级别
            const levels = Object.values(PraiseLevel);
            const currentIndex = levels.indexOf(baseLevel);
            if (currentIndex < levels.length - 1) {
                return levels[currentIndex + 1];
            }
        }

        return baseLevel;
    }

    /**
     * 显示称赞
     * @param level 称赞级别
     * @param eliminateCount 消除数量
     */
    private showPraise(level: PraiseLevel, eliminateCount: number): void {
        if (this.isShowingPraise) return;

        const config = this.praiseConfigs.find((cfg) => cfg.level === level);
        if (!config) return;

        this.isShowingPraise = true;

        // 播放音效
        this.playPraiseSound(config.sound);

        // 创建称赞文本
        this.createPraiseText(config, eliminateCount);

        // 创建粒子特效
        this.createParticleEffect(config);

        // 设置显示时间
        Laya.timer.once(config.duration, this, () => {
            this.isShowingPraise = false;
        });
    }

    /**
     * 创建称赞文本
     * @param config 称赞配置
     * @param eliminateCount 消除数量
     */
    private createPraiseText(config: PraiseConfig, eliminateCount: number): void {
        const praiseLabel = new Laya.Label();
        praiseLabel.text = GameLanguageMgr.getLanguage(config.text);
        praiseLabel.fontSize = config.fontSize;
        praiseLabel.color = config.color;
        praiseLabel.stroke = 3;
        praiseLabel.strokeColor = "#FFFFFF";
        praiseLabel.bold = true;
        praiseLabel.alpha = 0;
        praiseLabel.width = 600;

        // 使用内置对齐属性来居中文字
        praiseLabel.align = "center";
        praiseLabel.valign = "middle";
        // praiseLabel.bgColor = "#FFFFFF";

        // 设置位置（屏幕中央偏上）
        const x = Laya.stage.width / 2;
        const y = Laya.stage.height / 2 - 100;

        // 添加到容器后再设置位置，确保文字已渲染
        this.container.addChild(praiseLabel);
        console.log("createPraiseText x:", x, "y:", y, "width:", praiseLabel.width, "height:", praiseLabel.height);

        // 使用 pivot 来设置锚点为中心，然后设置位置
        // praiseLabel.pivot(praiseLabel.width / 2, praiseLabel.height / 2);
        praiseLabel.anchor(0.5, 0.5);
        praiseLabel.pos(x, y);

        this.container.addChild(praiseLabel);

        // 动画效果
        Laya.Tween.to(
            praiseLabel,
            {
                scaleX: config.scale,
                scaleY: config.scale,
                alpha: 1,
                y: y - 50
            },
            300,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                // 保持一段时间后消失
                Laya.timer.once(800, this, () => {
                    Laya.Tween.to(
                        praiseLabel,
                        {
                            scaleX: 1.5,
                            scaleY: 1.5,
                            alpha: 0,
                            y: y - 100
                        },
                        400,
                        Laya.Ease.backIn,
                        Laya.Handler.create(this, () => {
                            praiseLabel.removeSelf();
                        })
                    );
                });
            })
        );
    }

    /**
     * 创建粒子特效
     * @param config 称赞配置
     */
    private createParticleEffect(config: PraiseConfig): void {
        const centerX = Laya.stage.width / 2;
        const centerY = Laya.stage.height / 2 - 100;

        for (let i = 0; i < config.particleCount; i++) {
            const particle = new Laya.Sprite();

            // 随机粒子样式
            const particleType = Math.random();
            if (particleType < 0.3) {
                // 圆形粒子
                particle.graphics.drawCircle(0, 0, 3, config.color);
            } else if (particleType < 0.6) {
                // 方形粒子
                particle.graphics.drawRect(-2, -2, 4, 4, config.color);
            } else {
                // 星形粒子
                particle.graphics.drawPoly(0, 0, [0, -3, 1, -1, 3, -1, 1, 1, 2, 3, 0, 2, -2, 3, -1, 1, -3, -1, -1, -1], config.color);
            }

            particle.alpha = 0.8;
            particle.pos(centerX, centerY);
            this.container.addChild(particle);

            // 随机方向扩散
            const angle = (Math.PI * 2 * i) / config.particleCount + Math.random() * 0.5;
            const distance = 50 + Math.random() * 100;
            const targetX = centerX + Math.cos(angle) * distance;
            const targetY = centerY + Math.sin(angle) * distance;

            Laya.Tween.to(
                particle,
                {
                    x: targetX,
                    y: targetY,
                    alpha: 0,
                    scaleX: 0.5,
                    scaleY: 0.5
                },
                800 + Math.random() * 400,
                Laya.Ease.backOut,
                Laya.Handler.create(this, () => {
                    particle.removeSelf();
                })
            );
        }
    }

    /**
     * 播放称赞音效
     * @param soundName 音效名称
     */
    private playPraiseSound(soundName: string): void {
        // 使用音效管理器播放音效
        if (this.soundManager) {
            const level = soundName as PraiseLevel;
            this.soundManager.playPraiseSound(level);
        }

        // // 播放连击音效
        // if (this.comboCount >= 2) {
        //     this.soundManager.playComboSound(this.comboCount);
        // }
    }

    /**
     * 设置连击超时
     */
    private setComboTimeout(): void {
        Laya.timer.once(this.comboTimeout, this, () => {
            this.resetCombo();
        });
    }

    /**
     * 重置连击
     */
    private resetCombo(): void {
        this.comboCount = 0;
        this.lastEliminateTime = 0;
    }

    /**
     * 获取当前连击数
     */
    public getComboCount(): number {
        return this.comboCount;
    }

    /**
     * 强制重置连击
     */
    public forceResetCombo(): void {
        this.resetCombo();
    }

    /**
     * 清理资源
     */
    public clear(): void {
        this.container.removeChildren();
        this.resetCombo();
        this.isShowingPraise = false;
    }

    /**
     * 销毁
     */
    public destroy(): void {
        this.clear();
        if (this.container.parent) {
            this.container.removeSelf();
        }
    }
}
