import GameLanguageMgr from "../../common/GameLanguageMgr";
import { ClubTypeListItemBase } from "./ClubTypeListItem.generated";
const { regClass } = Laya;

@regClass('lH/RWSpjQtuPd9t0m34t5A==')
export class ClubTypeListItem extends ClubTypeListItemBase {
    isAddEvent: boolean;
    public set dataSource(value: any) {
        super.dataSource = value;
        if(value){
            this.tf_data.text = GameLanguageMgr.getLanguage(value.name)
        }
    }

    onDisable(): void {
    }

    private onChange(isSelect:boolean){
        if(isSelect){
            this.selectImg.visible = true;
            this.tf_data.color = "#ffffff";
        }else{
            this.tf_data.color = "#357cc0";
            this.selectImg.visible = false;
        }
    }
}
