/**
 * 跑马灯管理器
 * 用于管理游戏中的滚动公告
 */
import Signal from "../../global/event/Signal";
import { GameEvent } from "../../global/event/GameEvent";

class MarqueeManager {
    private static _instance: MarqueeManager;
    
    // 公告消息队列
    private _notices: string[] = [];
    
    // 是否正在显示公告
    private _isPlaying: boolean = false;
    
    // 当前显示的公告索引
    private _currentIndex: number = 0;
    
    // 文本组件
    private _textField: Laya.Text = null;
    
    // 容器对象
    private _container: Laya.Box = null;
    
    // 滚动速度(像素/帧)
    private _speed: number = 2;
    
    // 存储公告及其播放次数，每条公告播放两次后清除
    private _noticePlayCounts: Map<string, number> = new Map();
    
    // 是否在主界面
    private _isInMainScene: boolean = false;
    
    // 每条公告最大播放次数
    private _maxPlayCount: number = 1;
    
    // 标记当前文本是否已完全进入过可视区域
    private _hasFullyEntered: boolean = false;
    
    /**
     * 获取单例
     */
    public static getInstance(): MarqueeManager {
        if (!this._instance) {
            this._instance = new MarqueeManager();
        }
        return this._instance;
    }
    
    /**
     * 初始化跑马灯
     * @param container 跑马灯容器
     * @param textField 文本字段
     * @param speed 滚动速度
     */
    public init(container: Laya.Box, textField: Laya.Text, speed: number = 2): void {
        this._container = container;
        this._textField = textField;
        this._speed = speed;
        
        // 设置文本相关属性
        this._configureTextField();
        
        // 初始状态，文本不可见
        this._textField.visible = false;
        
        // 设置容器剪裁
        this._container.scrollRect = new Laya.Rectangle(0, 0, this._container.width, this._container.height);
        
        // 设置为在主界面
        this._isInMainScene = true;
        
        // 如果有存储的公告，开始播放
        this.checkAndPlayStoredNotices();
    }
    
    /**
     * 配置文本字段的属性
     */
    private _configureTextField(): void {
        if (!this._textField) return;
        
        // 确保文本不会自动换行
        this._textField.overflow = Laya.Text.VISIBLE;
        this._textField.wordWrap = false;
    }
    
    /**
     * 添加一条公告
     * @param notice 公告内容
     */
    public addNotice(notice: string): void {
        // 如果公告内容为空，不添加
        if (!notice || notice.trim() === '') return;
        
        // 记录添加前是否有公告
        const wasEmpty = this._notices.length === 0;
        
        // 如果该公告不在播放次数映射中，则添加并初始化播放次数为0
        if (!this._noticePlayCounts.has(notice)) {
            this._noticePlayCounts.set(notice, 0);
        }
        
        // 如果公告不在队列中，则添加到队列末尾
        if (this._notices.indexOf(notice) === -1) {
            this._notices.push(notice);
        }
        
        // 如果添加前是空的，添加后不是空的，并且在主界面，则触发事件通知主界面显示跑马灯框
        if (wasEmpty && this._notices.length > 0 && this._isInMainScene) {
            Signal.event(GameEvent.EVENT_NEW_NOTICE_ADDED);
        }
        
        // 如果在主界面且当前没有在播放，则开始播放
        if (this._isInMainScene && !this._isPlaying && this._container) {
            this.play();
        }
    }
    
    /**
     * 添加多条公告
     * @param notices 公告内容数组
     */
    public addNotices(notices: string[]): void {
        if (!notices || notices.length === 0) return;
        
        // 遍历所有公告，添加到队列
        for (let notice of notices) {
            this.addNotice(notice);
        }
    }
    
    /**
     * 清空公告队列
     */
    public clearNotices(): void {
        this._notices = [];
        this._isPlaying = false;
        this._currentIndex = 0;
        this._noticePlayCounts.clear();
        
        if (this._textField) {
            this._textField.visible = false;
        }
        
        Laya.timer.clearAll(this);
    }
    
    /**
     * 开始播放跑马灯
     */
    private play(): void {
        if (this._notices.length === 0 || !this._container) return;
        
        this._isPlaying = true;
        this.showCurrentNotice();
    }
    
    /**
     * 显示当前公告
     */
    private showCurrentNotice(): void {
        if (this._notices.length === 0) {
            this._isPlaying = false;
            return;
        }
        
        // 获取当前公告
        const notice = this._notices[this._currentIndex];
        
        // 设置文本内容
        this._textField.text = notice;
        
        // 确保文本字段重新计算尺寸
        this._textField.width = this._textField.textWidth;
        
        // 临时设为可见以便测量宽度
        this._textField.visible = true;
        
        // 重置标记，表示新的文本还未完全进入过可视区域
        this._hasFullyEntered = false;
        
        // 使用Laya.timer.frameOnce确保宽度在下一帧计算
        Laya.timer.frameOnce(1, this, () => {
            // 再次确认文本宽度，防止首次计算不准确
            this._textField.width = this._textField.textWidth;
            
            // 设置到容器右侧外部，开始从右向左移动
            this._textField.x = this._container.width;
            
            // 启动滚动动画
            Laya.timer.frameLoop(1, this, this.scrollText);
        });
    }
    
    /**
     * 滚动文本
     */
    private scrollText(): void {
        // 文本向左移动
        this._textField.x -= this._speed;
        
        // 检查文本是否全部进入可视区域
        // 文本最右边小于等于容器宽度时，说明文本已经全部显示在容器内部或部分开始离开容器
        if (!this._hasFullyEntered && (this._textField.x + this._textField.width) <= this._container.width) {
            this._hasFullyEntered = true;
        }
        
        // 只有文本已完全显示过（全部进入过可视区域），且文本完全离开可视区域后才完成一次播放
        // 文本右边界完全移出可视区域，表示最后一个字符也完全离开了可视区域
        if (this._hasFullyEntered && (this._textField.x + this._textField.width) <= 0) {
            // 停止当前滚动
            Laya.timer.clear(this, this.scrollText);
            
            // 获取当前公告
            const currentNotice = this._notices[this._currentIndex];
            
            // 只有在主界面才增加播放次数
            if (this._isInMainScene) {
                // 更新公告播放次数
                let playCount = this._noticePlayCounts.get(currentNotice) || 0;
                playCount++;
                this._noticePlayCounts.set(currentNotice, playCount);
            }
            
            const currentPlayCount = this._noticePlayCounts.get(currentNotice) || 0;
            
            // 只有在主界面并且公告已经播放了最大次数，才从队列中移除
            if (this._isInMainScene && currentPlayCount >= this._maxPlayCount) {
                this._notices.splice(this._currentIndex, 1);
                this._noticePlayCounts.delete(currentNotice);
                
                // 如果删除后索引超出范围，重置为0
                if (this._currentIndex >= this._notices.length) {
                    this._currentIndex = 0;
                }
            } else {
                // 移动到下一条公告
                this._currentIndex = (this._currentIndex + 1) % this._notices.length;
            }
            
            // 如果还有公告，继续显示
            if (this._notices.length > 0) {
                this.showCurrentNotice();
            } else {
                // 没有公告了，停止播放
                this._isPlaying = false;
                this._textField.visible = false;
                
                // 触发公告播放完毕事件，通知MainScene隐藏跑马灯框
                if (this._isInMainScene) {
                    Signal.event(GameEvent.EVENT_MARQUEE_EMPTY);
                }
            }
        }
    }
    
    /**
     * 暂停跑马灯
     */
    public pause(): void {
        Laya.timer.clear(this, this.scrollText);
        this._isPlaying = false;
    }
    
    /**
     * 继续跑马灯
     */
    public resume(): void {
        if (!this._isPlaying && this._notices.length > 0) {
            this.play();
        }
    }
    
    /**
     * 设置滚动速度
     * @param speed 速度（像素/帧）
     */
    public setSpeed(speed: number): void {
        this._speed = speed;
    }
    
    /**
     * 设置是否在主界面
     * @param isInMainScene 是否在主界面
     */
    public setInMainScene(isInMainScene: boolean): void {
        // 如果状态没有变化，不做处理
        if (this._isInMainScene === isInMainScene) return;
        
        this._isInMainScene = isInMainScene;
        
        // 如果进入主界面，检查并播放存储的公告
        if (isInMainScene) {
            // 如果离开主界面后又回来，重置所有公告的播放次数，确保每条公告都能再次完整播放
            if (this._notices.length > 0) {
                // 重置所有公告的播放次数
                for (const notice of this._notices) {
                    this._noticePlayCounts.set(notice, 0);
                }
                
                // 如果有新的公告要显示，触发事件通知显示跑马灯框
                Signal.event(GameEvent.EVENT_NEW_NOTICE_ADDED);
            }
            
            this.checkAndPlayStoredNotices();
        } else {
            // 如果离开主界面，暂停播放
            this.pause();
        }
    }
    
    /**
     * 检查并播放存储的公告
     */
    private checkAndPlayStoredNotices(): void {
        // 如果有存储的公告且在主界面，开始播放
        if (this._notices.length > 0 && this._isInMainScene && !this._isPlaying && this._container) {
            this.play();
        }
    }
    
    /**
     * 获取存储的公告列表
     * @returns 公告列表
     */
    public getStoredNotices(): string[] {
        return [...this._notices];
    }
    
    /**
     * 获取公告播放次数
     * @param notice 公告内容
     * @returns 播放次数
     */
    public getNoticePlayCount(notice: string): number {
        return this._noticePlayCounts.get(notice) || 0;
    }
    
    /**
     * 设置每条公告最大播放次数
     * @param count 最大播放次数
     */
    public setMaxPlayCount(count: number): void {
        if (count > 0) {
            this._maxPlayCount = count;
        }
    }
    
    /**
     * 判断是否有公告内容
     * @returns 是否有公告内容
     */
    public hasNotices(): boolean {
        return this._notices.length > 0;
    }
} 
export default MarqueeManager.getInstance();
