const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import { ItemItem } from "../../data/sheetItem/item/ItemItem";
import { ItemVo } from "../../data/vo/pack/ItemVo";
import SheetDataManager from "../../global/SheetDataManager";
import { KnapsackTipDialogBase } from "./KnapsackTipDialog.generated";

@regClass('or8jNdIhRpSbAG2JBhH+wA==')
export class KnapsackTipDialog extends KnapsackTipDialogBase {
    private itemVo: ItemVo;
    // private equipMenu:EquipMenuView;
    public m_strName: string = "我是OpenSceneRuntime";
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;

    public setOpenData(_data: any) {
        if (_data) {
            this.itemVo = _data;
            const itemId = this.itemVo.id;
            const itemItem: ItemItem = SheetDataManager.m_dicItems.get(itemId);

            this.item.dataSource = this.itemVo;

            this.tf_name.text = this.itemVo.itemName;
            if (itemItem) {
                this.txt_type.text = GameLanguageMgr.getLanguage(6060) + GameLanguageMgr.getLanguage(itemItem.type);

                this.txt_desc.text = GameLanguageMgr.getLanguage(itemItem.des);
                this.txt_desc.visible = itemItem.des !== 0;
            } else {
                this.txt_type.text = "";

                this.txt_desc.text = "";
            }
        }
    }

    public removeEvent(): void {}
}
