import { com } from "../../../network/pb/socket";
import { NumberUtil } from "../../../utils/NumberUtil";
import { RaceDto } from "../../dto/RaceDto";

export class RaceVo {
    public constructor() {}

    public raceDto: RaceDto;

    public playerNum: number; //参赛人数
    public isSign: boolean; //是否已报名

    getPoolType(): number {
        //1.报名费模式 2.空投模式
        if (this.raceDto.rewardMode == 1) {
            return this.raceDto.feeId;
        } else {
            return this.raceDto.symbolId;
        }
    }
    getPoolReward(): any {
        //1.报名费模式 2.空投模式
        if (this.raceDto.rewardMode == 1) {
            var balance = this.raceDto.feeNum * this.playerNum * 0.8;
            var reward = NumberUtil.filterNumFormat(balance, 2, true);
            return reward;
        } else {
            return this.raceDto.reward;
        }
    }
}
