    /**
     * 商城购买
     */
    private onRecruit(): void {
        // 检查按钮是否锁定，如果锁定则直接返回
        if (this.isButtonLocked) {
            return;
        }

        // 锁定按钮，1.5秒后解锁
        this.isButtonLocked = true;
        Laya.timer.once(this.buttonLockTime, this, () => {
            this.isButtonLocked = false;
        });

        const cmdId = com.snake.socket.MessageType.MSG_SHOP_BUY;
        var snakeItem: SnakeItem = SheetDataManager.m_dicSnakes.get(this.shopId);
        console.log(snakeItem);
        if (this.shopId) {
            const requestData = com.snake.socket.CS_SHOP_BUY.fromObject({
                id: this.shopId,
                symbolId: 10,
                num: 1
            });
            HallWebSocket.send(cmdId, requestData);
        }
    }

    /**
     * 处理代币余额更新事件
     * @param tokenData 资产数据数组
     */
    private onTokenBalanceUpdate(tokenData: TokenData[]): void {
        this.showAssetData(tokenData);
    }

    /**
     * 显示资产数据
     * @param tokenData 资产数据数组
     */
    private showAssetData(tokenData: TokenData[]) {
        //查找symbolId为10的资产数据
        const targetToken = tokenData.find((token) => token.symbolId === 10);
        const balance = targetToken ? targetToken.balance : 0;
        this.tf_usdt.text = NumberUtil.filterNumFormat(balance, 2, true);
    }

    onDisable(): void {
        this.removeEvent();
        // 重置按钮锁定状态
        this.isButtonLocked = false;
    }
