const { regClass } = Laya;
import { AiArenaStartDialogBase } from "./AiArenaStartDialog.generated";
import GlobalDataManager from "../../global/GlobalDataManager";
import NoticeMgr from "../notice/NoticeMgr";
import { NumberUtil } from "../../utils/NumberUtil";
import FrameAiManager from "../../game/ai/FrameAiManager";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import SoundMgr from "../../common/SoundMgr";

@regClass('tAeAnFihTPGN15jVQ97v8w==')
export class AiArenaStartDialog extends AiArenaStartDialogBase {
    private stars: Laya.Image[] = [];
    private powerIcons: Laya.Image[] = [];
    private isAnimating: boolean = false;

    onEnable(): void {
        this.createUI();
        this.updateDisplay();
        this.playOpenAnimation();
    }

    private createUI(): void {
        // 创建5个体力图标用于动画
        for (let i = 0; i < 5; i++) {
            const icon = new Laya.Image();
            icon.skin = this.img_power.skin; //"res/common/icon_power_small.png";
            icon.width = 40;
            icon.height = 40;
            icon.x = this.powerContainer.x + 60 + i * 25;
            icon.y = this.powerContainer.y + 15;
            icon.visible = false;
            this.addChild(icon);
            this.powerIcons.push(icon);
        }

        // 初始化星级显示
        for (let i = 0; i < 3; i++) {
            var star = (this as any)["img_star_" + (i + 1)];
            this.stars.push(star);
            star.alpha = 0;
        }

        // 绑定事件
        this.startButton.on(Laya.Event.CLICK, this, this.onStartClick);
    }

    private updateDisplay(): void {
        const playerDto = GlobalDataManager.playerDto;
        if (!playerDto) return;

        // 更新体力值
        this.powerLabel.text = `${playerDto.power || 0}`;

        // 获取最好成绩
        const bestRecord = this.getBestRecord();

        // 更新星星显示

        const starCount = NumberUtil.calculateStarCount(bestRecord.score);

        for (let i = 0; i < 3; i++) {
            const star = this.stars[i];
            if (i < starCount) {
                star.alpha = 1;
            } else {
                star.alpha = 0;
            }
        }

        // 更新分数显示
        this.bestScoreLabel.text = ` ${bestRecord.score}`;

        // 检查体力是否足够
        this.startButton.disabled = (playerDto.power || 0) < 5;
        this.startButton.alpha = this.startButton.disabled ? 0.5 : 1;
    }

    private getBestRecord(): { score: number; stars: number } {
        var aiScore = GlobalDataManager.playerDto.aiScore;
        var starNum = NumberUtil.calculateStarCount(aiScore);
        return { score: aiScore, stars: starNum };
    }

    private async onStartClick(): Promise<void> {
        if (this.isAnimating) return;

        const playerDto = GlobalDataManager.playerDto;
        if (!playerDto || (playerDto.power || 0) < 5) {
            // 体力不足提示
            NoticeMgr.notice(GameLanguageMgr.getLanguage(2013)); //精力不足
            return;
        }

        this.isAnimating = true;

        // 播放体力消耗动画
        await this.playPowerConsumeAnimation();

        // // 扣除体力
        // playerDto.power = (playerDto.power || 0) - 5;
        // GlobalDataManager.instance.savePlayerData();

        // 进入PVE比赛
        this.startPVEMatch();
        this.isAnimating = false;
    }

    private async playPowerConsumeAnimation(): Promise<void> {
        SoundMgr.playSoundByName(SoundMgr.soundName_magic);//播放体力声音
        return new Promise((resolve) => {
            // 显示5个体力图标
            var i = 0;
            this.powerIcons.forEach((icon) => {
                icon.visible = true;
                icon.alpha = 1;
                icon.scaleX = icon.scaleY = 1;
    
                icon.x = this.powerContainer.x + 60 + i * 25;
                icon.y = this.powerContainer.y + 15;
    
                i++;
            });
    
            let completedCount = 0;
            const totalIcons = this.powerIcons.length;
    
            // 依次移动每个体力图标到开始按钮
            this.powerIcons.forEach((icon, index) => {
                Laya.Tween.to(
                    icon,
                    {
                        x: this.startButton.x - 90,
                        y: this.startButton.y,
                        scaleX: 0.8,
                        scaleY: 0.8,
                        alpha: 0.5
                    },
                    800 + index * 50,  // 从1500+100改为800+50，动画更快
                    Laya.Ease.backIn,
                    Laya.Handler.create(this, () => {
                        icon.visible = false;
                        completedCount++;
    
                        if (completedCount === totalIcons) {
                            // 播放按钮闪烁效果
                            this.playButtonFlash();
    
                            // 延迟一下再完成
                            Laya.timer.once(150, this, () => {  // 从300改为150毫秒
                                resolve();
                            });
                        }
                    })
                );
            });
    
            // 更新体力显示
            Laya.timer.once(100, this, this.updatePower);  // 从200改为100毫秒
        });
    }

    private updatePower(): void {
        // 更新体力值
        const playerDto = GlobalDataManager.playerDto;
        this.powerLabel.text = `${playerDto.power - 5}`;
    }

    private playButtonFlash(): void {
        // 按钮闪烁效果
        Laya.Tween.to(
            this.startButton,
            { scaleX: 1.1, scaleY: 1.1 },
            150,
            Laya.Ease.backOut,
            Laya.Handler.create(this, () => {
                Laya.Tween.to(this.startButton, { scaleX: 1, scaleY: 1 }, 150, Laya.Ease.backOut);
            })
        );
    }

    private startPVEMatch(): void {
        FrameAiManager.sendAiEnter();
        // 关闭当前对话框
        // this.close();
        // 进入AI竞技场场景
        // ModuleManager.instance.showModule(AiArenaScene, null);
    }

    private playOpenAnimation(): void {
        // 对话框打开动画
        // this.scaleX = this.scaleY = 0.5;
        // this.alpha = 0;

        // Laya.Tween.to(
        //     this,
        //     {
        //         scaleX: 1,
        //         scaleY: 1,
        //         alpha: 1
        //     },
        //     300,
        //     Laya.Ease.backOut
        // );

        // 星星闪烁动画
        Laya.timer.once(500, this, () => {
            this.playStarTwinkle();
        });
    }

    private playStarTwinkle(): void {
        this.stars.forEach((star, index) => {
            if (star.alpha === 1) {
                Laya.timer.loop(2000 + index * 200, this, () => {
                    Laya.Tween.to(
                        star,
                        { scaleX: 1.2, scaleY: 1.2 },
                        200,
                        Laya.Ease.sineOut,
                        Laya.Handler.create(this, () => {
                            Laya.Tween.to(star, { scaleX: 1, scaleY: 1 }, 200, Laya.Ease.sineOut);
                        })
                    );
                });
            }
        });
    }

    onDestroy(): void {
        // 清理定时器
        Laya.timer.clearAll(this);

        // 清理补间动画
        this.powerIcons.forEach((icon) => {
            Laya.Tween.clearAll(icon);
        });
        this.stars.forEach((star) => {
            Laya.Tween.clearAll(star);
        });
        Laya.Tween.clearAll(this.startButton);
        Laya.Tween.clearAll(this);

        super.onDestroy();
    }


}
