import { StageCellItem } from "../../data/sheetItem/match/StageCellItem";
import SheetDataManager from "../../global/SheetDataManager";
import CellModel from "../model/CellModel";
import { CELL_STATUS } from "../model/ConstValue";
import { ElementCellViewBase } from "./ElementCellView.generated";
const { regClass } = Laya;

@regClass('CsfSDFFgR9O+gUasHp/8/g==')
export default class ElementCellView extends ElementCellViewBase {
    private _animator: Laya.Animator2D;
    // private img: Laya.Image;
    model: CellModel;
    cellCfg: StageCellItem;

    onEnable(): void {
        // 初始化图片和动画节点
        // this.img = this.getChildByName("img") as Laya.Image;
        this._animator = this.getComponent<Laya.Animator2D>(Laya.Animator2D);
    }

    /**
     * 初始化元素表现
     * @param model CellModel
     */
    initWithModel(model: CellModel): void {
        this.model = model;
        // 查表获取icon
        this.cellCfg = SheetDataManager.m_dicStageCells.get(model.type);
        // this.cellCfg = CELL_TYPE_CONFIGS.find((cfg) => cfg.id === model.type);
        if (this.cellCfg) {
            this.img.skin = this.cellCfg.icon;
        }
        // 状态动画
        if (model.status === CELL_STATUS.NORMAL) {
            this._animator?.stop();
        } else {
            this._animator?.play(model.status);
        }
        this.selectBg.visible = false;
    }

    /**
     * 设置选中状态
     * @param flag 是否选中
     */
    setSelect(flag: boolean): void {
        if (flag) {
            // 选中状态处理
            if (this.model.status === CELL_STATUS.NORMAL || this.model.status === CELL_STATUS.BIRD) {
                // 播放选中动画
                this._animator.play(CELL_STATUS.CLICK);
                // this.playSelectAnimation();
            }
        } else {
            // 取消选中状态
            if (this.selectBg.visible && this.model.status === CELL_STATUS.NORMAL) {
                // 恢复默认状态
                Laya.Tween.killAll(this);
                // Laya.Tween.killAll(this, false);
                this._animator.stop();
                if (this.cellCfg) {
                    this.img.skin = this.cellCfg.icon;
                }
                // this.rotation = 0;
                // this.scale(1, 1);
                // this.loadTextureForType(this.model.type);
            }
        }

        this.selectBg.visible = flag; // 显示/隐藏选中背景
    }

    /**
     * 消除时缩小+变透明动画
     */
    playDieEffect(): void {
        Laya.Tween.to(
            this,
            { scaleX: 0.2, scaleY: 0.2, alpha: 0 },
            200,
            Laya.Ease.quadIn,
            Laya.Handler.create(this, () => {
                this.removeSelf();
            })
        );
    }
    playBirdGuangEffect() {
        if (this.cellCfg && this._animator) {
            this._animator?.play("effect");
        }
    }

    onDisable(): void {
        Laya.Tween.killAll(this);
        this.cellCfg = null;
    }
}
